const memberLinks=[['dashboard','⌂','ホーム'],['schedule','▦','練習・日程・出欠・体調報告'],['results','◷','試合結果・動画'],['skill-videos','▷','スキルアップ動画'],['announcements','✉','クラブからのお知らせ'],['surveys','✓','保護者アンケート'],['payments','¥','月謝支払い'],['finance-report','¥','会計へ報告'],['shop','◇','スクール内物販'],['messages','✉','諸連絡'],['board','☷','掲示板'],['injuries','♡','怪我報告'],['basket-notes','▤','バスケノート'],['worksheets','▤','ワークシート'],['school-reports','▤','成績報告'],['member-guide','?','会員ページの使い方']];
const serviceLabels=Object.fromEntries(memberLinks.map(x=>[x[0],x[2]]));
serviceLabels.payment_preferences='支払い方法の希望';
function paymentPreferences(){const b=data.family_billing||{};return `<div class="card payment-preferences"><h2>会費のお支払い</h2>${familyBillingPreview()}${b.next?`<details><summary>次回のお支払い予定</summary><p>${esc(billingPeriodLabel(b.next))}</p><p>お支払い合計金額：${b.next.total==null?'金額未設定':'¥'+b.next.total.toLocaleString()}</p><p class="hint">現在の設定に基づく予定です。実際の自動請求はまだ行いません。</p></details>`:''}<p>支払い期間：<strong>${esc(b.cycle||'半年払い')}</strong></p><form onsubmit="savePaymentPreferences(event)">${selectField('支払い方法','method',[['','選択してください'],'クレジットカード','コンビニ決済'],b.method||'')}<p class="hint">方法はご家庭で共通です。一度保存すると次回も表示され、いつでも変更できます。カード情報・口座情報の登録や自動引き落としは、このデモでは行いません。</p><div class="error" role="alert"></div><div class="payment-action-row"><button type="submit" class="outline">${b.method?'支払い方法を変更・保存':'支払い方法を保存'}</button><a class="btn lime" href="#checkout">${b.receipt?'支払い手続きの記録を見る':'支払い手続きへ進む'}</a></div></form></div>${familyPaymentHistory()}`;}
async function savePaymentPreferences(ev){ev.preventDefault();await submit(ev,'portal',{action:'payment_preferences',...Object.fromEntries(new FormData(ev.target))},'支払い方法を保存し、Excelを更新しました。');}
function billingAdminSettings(){if(data.billing_plan)return billingPlanPanel();const s=data.portal?.billing_settings||{cycle:'半年払い'};return `<div class="card payment-preferences"><h2>会費の支払い期間（管理者設定）</h2>${feeInputGuide()}<p>会員ページの表示と、全会員のExcel一覧に反映されます。</p>${user.role==='admin'?`<form onsubmit="saveBillingSettings(event)">${selectField('支払い期間','cycle',['毎月払い','半年払い','年払い'],s.cycle)}${field('対象期間の開始月','start_month',s.start_month||new Date().toISOString().slice(0,7),'month')}<p class="hint">デモの表示設定です。本番の契約・請求額・次回課金日はまだ変更しません。</p><div class="error" role="alert"></div><button class="lime">設定を保存・Excelに反映</button></form>`:`<p>現在：<b>${esc(s.cycle)}</b>（変更は管理者のみ）</p>`}<p class="hint">最終更新：${esc(s.updated||'初期設定')}</p><a class="text-link" href="/basketball-club/api/excel">会費管理を含むExcelをダウンロード</a></div>`;}
async function saveBillingSettings(ev){ev.preventDefault();await submit(ev,'portal',{action:'billing_settings',...Object.fromEntries(new FormData(ev.target))},'支払い期間を変更し、会員表示とExcelに反映しました。');}
function homeAnnouncements(){const news=(data.portal?.items||[]).filter(x=>x.kind==='announcements');return `<section class="home-announcements" aria-label="クラブからのお知らせ"><div class="home-announcements-heading"><span aria-hidden="true">📣</span><h2>クラブからのお知らせ</h2></div>${news.length?`<ul>${news.slice(0,3).map(x=>`<li><a href="#announcements" data-id="${esc(x.id)}" onclick="event.preventDefault();openAnnouncement(this.dataset.id)">${esc(x.title)}</a>${articleNew('announcements',x.id)}</li>`).join('')}</ul>`:'<p>現在、新しいお知らせはありません。</p>'}</section>`;}
function memberHomeLinks(){return `<div class="member-welcome"><span class="eyebrow">SHINING CHEETAHS / MEMBER PORTAL</span><h2>チームとつながる、会員ホーム。</h2><p>日程の確認からコーチへの連絡まで、ここから。</p></div>${homeAnnouncements()}${memberProgressCards()}<div class="member-shortcuts">${visibleMemberLinks().slice(1).map(([id,icon,label])=>`<a href="#${id}"><span class="shortcut-icon-row"><span class="shortcut-icon">${icon}</span><span data-new-nav="${id}">${navNew(id)}</span></span>${label}</a>`).join('')}</div>`;}

function serviceEntries(kind,staff=false){const entries=(data.portal?.entries||[]).filter(x=>x.kind===kind);if(['messages','injuries'].includes(kind))entries.sort((a,b)=>String(b.created||'').localeCompare(String(a.created||'')));const cards=entries.map(x=>`<article class="card service-entry" data-service-entry="${esc(x.id)}"><div class="toolbar"><b>${esc(x.name)}</b>${articleNew(kind,x.id)}<time class="hint">${esc(x.created)}</time>${kind==='board'?'':`<span class="tag">${esc(x.status)}</span>`}</div><p class="service-text">${esc(x.body)}</p>${staff&&(x.status==='未確認'||['messages','injuries'].includes(kind))?`<button class="outline small" onclick="portalReview('${x.id}',${x.status!=='確認済み'})">${x.status==='確認済み'?'未確認に戻す':'確認済みにする'}</button>`:''}</article>`);if(!cards.length)return '<div class="card empty">まだ記録はありません。</div>';if(staff&&kind==='injuries'&&cards.length>2)return cards.slice(0,2).join('')+`<details class="injury-more-reports"><summary>続きを見る（残り${cards.length-2}件）</summary>${cards.slice(2).join('')}</details>`;return cards.join('');}
function serviceForm(kind,itemId=''){
 let fields=kind==='board'?field('題名','title')+'<label class="field">添付（写真・PDF・CSV）<input name="attachments" type="file" multiple accept=".jpg,.jpeg,.png,.webp,.pdf,.csv"></label><p class="hint">合計30件まで、1件5MB以下。</p>':'';
 if(kind==='injuries')return `<form class="service-form" onsubmit="portalSubmit(event,'injuries','')">${reportQuestions('injuries').map(q=>reportInput(q,q.type==='date'?new Date().toLocaleDateString('sv-SE'):'',true)).join('')}<div class="error" role="alert"></div><button class="lime">コーチに送信</button></form>`;
 if(kind==='shop')fields=selectField('サイズ','size',['130','140','150','160','S','M','L','XL'])+'<label class="field">数量<input name="quantity" type="number" value="1" min="1" max="20" required></label>';
 if(kind==='messages')fields=selectField('連絡の種類','message_type',[['','選択してください'],'欠席連絡','早退連絡','遅刻連絡'],'')+'<p class="hint">送信内容は管理者・担当コーチの諸連絡に保存されます。LINE通知は現在未接続です。</p>';
 const label=kind==='surveys'?'回答':kind==='injuries'?'状況・受診状況・コーチへの連絡':kind==='shop'?'連絡事項（任意）':'内容';
 return `<form class="service-form" onsubmit="portalSubmit(event,'${kind}','${itemId}')">${fields}<label class="field">${label}<textarea name="body" maxlength="3000" ${kind==='shop'?'':'required'}></textarea></label><div class="error" role="alert"></div><button class="lime">${kind==='shop'?'デモ注文を保存':kind==='surveys'?'回答を保存':kind==='board'?'掲示板に投稿':'コーチに送信'}</button></form>`;
}
function memberService(kind){
 const descriptions={announcements:'クラブからの連絡を確認できます。',surveys:'回答は本人とコーチ・管理者のみが確認できます。',payments:'デモ画面です。実際の決済・カード情報の入力はありません。',shop:'デモ注文を試せます。実際の商品発送・決済は発生しません。',messages:'コーチへの個別連絡です。他の会員には表示されません。',board:'管理者・コーチからの投稿を確認できます。個別の相談は「諸連絡」へ。',injuries:'本人とコーチ・管理者のみが確認できます。'};
 let html=heading(serviceLabels[kind],descriptions[kind]);
 if(kind==='announcements')return html+announcementList();
 if(kind==='surveys')return html+parentSurveys();
 if(kind==='payments')return html+paymentPreferences();
 if(kind==='shop')return html+shopPage();
 if(kind==='board')return html+(user.role!=='member'?`<div class="card"><h2>掲示板に投稿する</h2>${serviceForm('board')}</div><h2 class="service-history">公開中の投稿</h2>`:'')+boardList();
 if(kind==='messages')return html+memberMessagesPage();
 if(['injuries'].includes(kind))return html+`<div class="card"><h2>${kind==='injuries'?'怪我を報告する':'連絡する'}</h2>${serviceForm(kind)}</div><details class="injury-report-history"><summary><span class="history-show">報告履歴を見る</span><span class="history-hide">報告履歴を閉じる</span></summary><section class="injury-history-content"><h2>報告履歴</h2>${serviceEntries(kind)}</section></details>`;
 const items=(data.portal?.items||[]).filter(x=>x.kind===kind);
 html+=`<div class="service-grid">${items.map(x=>{const existing=(data.portal?.entries||[]).find(e=>e.kind===kind&&e.item_id===x.id&&e.user_id===user.id);return `<article class="card"><span class="tag">${existing?esc(existing.status):kind==='announcements'?'CLUB NEWS':'受付中'}</span><h2>${esc(x.title)}</h2><p class="service-text">${esc(x.body)}</p>${['payments','shop'].includes(kind)?`<p class="service-price">¥${Number(x.amount).toLocaleString()} <small>サンプル${kind==='shop'?'・1点あたり':''}</small></p>`:''}${kind==='payments'?`<button class="lime" ${existing?'disabled':''} onclick="demoPayment('${x.id}',this)">${existing?'デモ支払い記録済み':'デモ支払いを試す'}</button>`:kind==='announcements'?'':serviceForm(kind,x.id)}</article>`}).join('')||'<div class="card empty">現在、掲載はありません。</div>'}</div>`;
 if(kind!=='announcements')html+='<h2 class="service-history">自分の履歴</h2>'+serviceEntries(kind);
 return html;
}
async function portalSubmit(ev,kind,itemId){ev.preventDefault();const values=Object.fromEntries(new FormData(ev.target));let body=values.body||'';if(kind==='board')body=values.title+'\n\n'+body;if(kind==='injuries')body=reportQuestions('injuries').map(q=>q.label+'：'+(values[q.id]||'')).join('\n');if(kind==='shop')body=`サイズ：${values.size}\n数量：${values.quantity}\n${body}`;let uploads=[];if(kind==='board'){try{const files=[...ev.target.elements.attachments.files];if(files.length>30)throw Error('添付は30件までです。');for(const file of files){if(file.size>5*1024*1024)throw Error('1件5MB以下にしてください。');uploads.push({name:file.name,content:await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(Error('ファイルを読み込めません。'));reader.readAsDataURL(file);})});}}catch(e){ev.target.querySelector('.error').textContent=e.message;return;}}await submit(ev,'portal',{kind,item_id:itemId,body,uploads,...(kind==='messages'?{message_type:values.message_type}:{})},kind==='board'?'投稿しました。':'保存しました。スタッフ画面で確認できます。');}
async function demoPayment(id,b){b.disabled=true;try{await api('portal',{kind:'payments',item_id:id,body:'デモ支払い操作完了（実際の請求・決済なし）'});await refresh();toast('デモ支払いを記録しました。実際の決済はありません。');}catch(e){toast(e.message);b.disabled=false;}}
async function portalReview(id,reviewed=true){const card=[...document.querySelectorAll('[data-service-entry]')].find(el=>el.dataset.serviceEntry===id),button=card?.querySelector('button');if(button)button.disabled=true;try{await api('portal',{action:'review',id,reviewed});const fresh=await api('data');data=fresh;renderEditToken=fresh.edit_token||'';const entry=fresh.portal?.entries.find(x=>x.id===id);if(card&&entry){const status=card.querySelector('.toolbar>.tag');if(status)status.textContent=entry.status;if(button){const confirmed=entry.status==='確認済み';button.textContent=confirmed?'未確認に戻す':'確認済みにする';button.onclick=()=>portalReview(id,!confirmed);}}toast(reviewed?'確認済みにしました。':'未確認に戻しました。');}catch(e){toast(e.message);}finally{if(button)button.disabled=false;}}
function adminFold(title,content){return `<details class="card service-admin-fold"><summary><b>${esc(title)}</b></summary><div class="service-admin-content">${content}</div></details>`;}
function portalAdmin(){return heading('会員向けサービス管理','各項目を開くと、掲載内容や回答・対応状況を確認できます。')+(user.role==='admin'?adminFold('会費の設定',billingAdminSettings()+feeAdjustmentsPanel()):'')+adminFold('クラブからのお知らせ',publicationManager('announcements'))+adminFold('保護者アンケートの回答・報告',publicationManager('surveys'))+adminFold('スクール内物販の回答・報告',publicationManager('shop')+shopAdmin())+adminFold('掲示板',boardList())+(user.role==='admin'?adminFold('月謝支払いの回答・報告',memberPaymentPanel()):'')+['messages','injuries'].map(k=>adminFold(k==='injuries'?'怪我の報告':'諸連絡',(k==='messages'?staffMessagesPanel():serviceEntries(k,true)))).join('');}

function portalItemForm(kind,id=''){if(kind==='shop'){shopProductForm(id);return;}if(id.startsWith('excel-notice-')){toast('このお知らせは入力用Excelで編集してください。');return;}const item=(data.portal?.items||[]).find(x=>x.id===id)||{};modal(serviceLabels[kind]+'を編集',`<form onsubmit="savePortalItem(event,'${kind}','${id}')">${kind==='surveys'?surveyConfigFields(id):''}${field('タイトル','title',item.title||'')}<label class="field">内容<textarea name="body" required maxlength="4000">${esc(item.body||'')}</textarea></label>${kind==='announcements'?announcementAttachmentFields(id):''}${['payments','shop'].includes(kind)?field('サンプル金額（円）','amount',item.amount||0,'number'):''}<div class="error" role="alert"></div><div class="dialog-actions">${id?`<button type="button" class="outline" onclick="deletePortalItem('${id}')">掲載を削除</button>`:''}<button class="lime">保存</button></div></form>`);}
async function savePortalItem(ev,kind,id){ev.preventDefault();try{const f=new FormData(ev.target),payload={...Object.fromEntries(f),action:'item',kind,id};if(kind==='announcements'){const files=[...ev.target.elements.notice_files.files];payload.keep_files=f.getAll('notice_keep');payload.uploads=[];delete payload.notice_files;delete payload.notice_keep;if(files.length+payload.keep_files.length>30)throw Error('添付は合計30件までです。');for(const file of files){if(file.size>5*1024*1024)throw Error('添付は1件5MB以下にしてください。');payload.uploads.push({name:file.name,content:await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=()=>reject(Error('ファイルを読み込めません。'));r.readAsDataURL(file);})});}}await submit(ev,'portal',payload,'掲載内容を保存しました。');}catch(e){ev.target.querySelector('.error').textContent=e.message;}}

async function deletePortalItem(id){if(!confirm('この掲載を削除しますか？過去の回答・記録は残ります。'))return;try{await api('portal',{action:'delete',id});$('#modal').close();await refresh();}catch(e){toast(e.message);}}
function billingPeriodLabel(b){const fmt=v=>v?Number(v.slice(0,4))+'年'+Number(v.slice(5))+'月':'';return fmt(b.start_month)+'〜'+fmt(b.end_month)+'分';}
function familyBillingPreview(){const b=data.family_billing;if(!b)return '';const shown=b.receipt||b;return `<div class="card"><h3>ご家庭のお支払い対象</h3><p><strong>${esc(billingPeriodLabel(shown))}</strong></p>${shown.lines.map(v=>`<div class="info-row"><span>${esc(v.name)}</span><b>${v.amount==null?'金額未設定':'¥'+Number(v.amount).toLocaleString()}</b></div>${v.period_start?`<p class="hint">対象期間：${esc(v.period_start)}〜${esc(v.period_end)}</p>`:''}${v.components?`<div class="hint">${v.components.map(c=>esc(c.label)+'：'+(c.amount==null?'未設定':'¥'+c.amount.toLocaleString())).join(' ／ ')}${v.annual_skipped?' ／ 年会費：4月開始の期間以外は加算なし':''}</div>`:''}`).join('')}<p>お支払い合計金額：<strong>${shown.total==null?'金額未設定':'¥'+Number(shown.total).toLocaleString()}</strong></p><p class="hint">お子さまの切り替えに関係なく、ご家庭全員分をまとめて表示します。${b.family_override?'家庭別に設定した割引等を含む合計金額です。':''}</p>${b.receipt?'<span class="tag">デモ手続き済み（実決済なし）</span>':''}</div>`;}
function familyCheckout(){const b=data.family_billing||{};return heading('お支払い手続き','ご家庭全員分をまとめて確認します。')+`<div class="card">${familyBillingPreview()}<p>支払い方法：<strong>${esc(b.receipt?.method||b.method||'未登録')}</strong></p>${b.receipt?'<p>この対象期間は手続き済みです。兄弟の画面からも重ねて手続きできません。</p>':`<p>${b.method==='コンビニ決済'?'本番では、コンビニでお支払いいただく番号と支払期限を表示します。':'本番では、決済サービスの安全なカード入力画面に進みます。'}</p><p class="hint">現在は画面遷移のデモです。実在するカード番号・銀行口座情報は入力しません。</p>${b.total==null?'<p>合計金額が未設定です。管理者がExcelで会費金額を設定すると手続きを試せます。</p>':''}<button class="lime" ${b.total==null||!b.method?'disabled':''} onclick="completeFamilyCheckout(this)">デモの手続き完了を試す（実決済なし）</button>`}<p><a href="#payments">支払い方法・請求内容に戻る</a></p></div>`;}
async function completeFamilyCheckout(button){button.disabled=true;try{await api('family_checkout',{revision:data.family_billing.revision});await refresh();toast('デモ手続きを記録しました。実際の支払いは発生していません。');}catch(e){toast(e.message);button.disabled=false;}}
function feeInputGuide(){return `<p>金額は固定PCの data/会費金額設定.xlsx で設定します。デモ起動中、保存後約5秒で取り込みます。</p><p class="hint">${esc(data.fee_input_status?.message||'未取り込み')} ${esc(data.fee_input_status?.updated||'')}</p><p class="hint">会員行で各人の金額、家庭行で家族全員分の合計金額を設定できます。家庭行がある場合はそちらを優先します。空欄は未設定、0は無料です。支払い期間ごとの1回分の税込金額を入力してください。</p>`;}
const scoreFields=[['points','得点'],['fouls','ファウル'],['rebounds','リバウンド'],['assists','アシスト'],['steals','スティール'],['blocks','ブロック'],['turnovers','ターンオーバー']];
function demoScoreParts(total,weights){const parts=weights.map(w=>Math.floor(total*w/weights.reduce((a,b)=>a+b,0)));let left=total-parts.reduce((a,b)=>a+b,0);for(let i=0;left>0;i++,left--)parts[i%parts.length]++;return parts;}
function demoScoreRows(result){const points=demoScoreParts(result.ours,[10,8,6,4,4,2,2]);return ['山田 りく','田中 そうた','佐藤 ゆうと','高橋 はるき','伊藤 かい','渡辺 あおい','中村 けんと','小林 れん'].map((name,i)=>({name,starter:i<5,number:String(i+4),participation:i===7?'ベンチ（出場なし）':'出場',points:points[i]||0,fouls:i===7?0:[2,1,3,2,1,0,1][i],rebounds:i===7?0:[6,4,5,3,2,1,2][i],assists:i===7?0:[3,4,1,2,1,1,0][i],steals:i===7?0:[2,1,2,0,1,0,1][i],blocks:i===7?0:[1,0,2,0,0,0,0][i],turnovers:i===7?0:[2,1,2,1,0,1,0][i]}));}
function gameStatsPanel(result,staff){
 const publication=data.game_stats?.publications.find(p=>p.result_id===result.id),saved=(data.game_stats?.rows||[]).filter(r=>r.result_id===result.id),sample=!publication&&!saved.length&&['r1','sample-result-sep05','sample-result-sep06','sample-result-sep12'].includes(result.id),rows=sample?demoScoreRows(result):saved;
 const wholeTeam=sample||staff||publication?.visibility==='team';
 return `<section class="game-records">${sample?'<p class="tag">仮のチームスコア</p><p class="hint">選手名・各選手の記録・クォーター別得点は、表示確認用の架空データです。</p>':''}${sample?`<div class="table-wrap"><table class="quarter-scores"><thead><tr><th>チーム</th>${[1,2,3,4].map(q=>`<th>${q}Q</th>`).join('')}<th>合計</th></tr></thead><tbody>${[['CHEETAHS',result.ours,[9,8,10,9]],[result.opponent,result.theirs,[8,9,7,8]]].map(([name,total,weights])=>`<tr><th>${esc(name)}</th>${demoScoreParts(total,weights).map(n=>`<td>${n}</td>`).join('')}<td><strong>${total}</strong></td></tr>`).join('')}</tbody></table></div>`:''}${user.role==='admin'?`<div class="toolbar"><button class="lime" onclick="scoreImportForm('${result.id}')">PDF・写真・CSVから読み込む</button><button class="outline" onclick="gameStatsForm('${result.id}')">記録を確認・公開</button></div><p class="hint">${({draft:'下書き',personal:'各本人のみ公開',team:'会員にベンチ全員分を公開'})[publication?.visibility]||'実際の記録は未登録'}</p>`:''}${rows.length?`<p class="hint"><span class="starter-name">青字・太字の選手名</span>＝スタメン</p><div class="table-wrap team-score-table"><table><thead><tr><th>選手・背番号</th><th>出場状況</th>${scoreFields.map(([,label])=>`<th>${label}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><td><span class="${r.starter?'starter-name':''}">${esc(r.name)}</span><br>#${esc(r.number||'—')}</td><td>${esc(r.participation?.includes('出場なし')?'':r.participation||'')}</td>${scoreFields.map(([key])=>`<td>${r[key]??'—'}</td>`).join('')}</tr>`).join('')}</tbody><tfoot><tr><th colspan="2">${wholeTeam?'チーム合計':'表示中の記録の合計'}</th>${scoreFields.map(([key])=>`<td><strong>${rows.every(r=>r[key]!=null)?rows.reduce((sum,r)=>sum+r[key],0):'—'}</strong></td>`).join('')}</tr></tfoot></table></div>`:'<p class="hint">この試合のスコアシート記録はまだ公開されていません。</p>'}</section>`;
}

