function gameStatsForm(id,asPage=false){
 const records=(data.game_stats?.rows||[]).filter(r=>r.result_id===id),pub=data.game_stats?.publications.find(p=>p.result_id===id);
 const members=data.users.filter(u=>u.role==='member'&&(u.active||records.some(r=>r.user_id===u.id)));
 const body=`<form onsubmit="saveGameStats(event,'${id}')"><p>保存する選手にチェックを入れて記録を入力してください。「新規追加」では未登録の選手を選んで入力欄へ移動できます。空欄は未記録、0は実績なしとして保存します。</p>${selectField('公開範囲','visibility',[['draft','下書き（スタッフのみ）'],['personal','各会員は自分の記録のみ'],['team','会員はベンチメンバー全員も閲覧可能']],pub?.visibility||'draft')}<div class="stack">${members.map(u=>{const r=records.find(r=>r.user_id===u.id)||{};return `<fieldset class="card" data-score-member="${esc(u.id)}"><legend><label><input type="checkbox" name="included" value="${esc(u.id)}" ${r.user_id?'checked':''}> ${esc(u.name)}</label></legend><div class="form-grid">${field('背番号','number_'+u.id,r.number||'','text',false)}${selectField('出場状況','participation_'+u.id,['未確認','出場',['ベンチ（出場なし）','出場なし']],r.participation||'未確認')}<label class="check-row"><input type="checkbox" name="starter_${u.id}" ${r.starter?'checked':''}>スタメン</label>${scoreFields.map(([key,label])=>`${scoreNumberControl(label,key+'_'+u.id,r[key])}`).join('')}</div></fieldset>`;}).join('')}</div><div class="error" role="alert"></div><label class="field" data-score-add hidden>追加する選手<select onchange="addGameStatsMember(this)"><option value="">選手を選択してください</option>${members.filter(u=>!records.some(r=>r.user_id===u.id)).map(u=>`<option value="${esc(u.id)}">${esc(u.name)}</option>`).join('')}</select><span class="hint" data-score-add-message></span></label><div class="dialog-actions"><button type="button" class="outline" onclick="openGameStatsAdd(this)">＋ 新規追加</button><button class="lime">記録を保存</button></div></form>`;
 if(asPage)return body;modal('個人記録',body);
}
function openGameStatsAdd(button){const box=button.form.querySelector('[data-score-add]');box.hidden=false;box.querySelector('[data-score-add-message]').textContent=box.querySelector('select').options.length===1?'追加できる選手は全員表示済みです。':'';box.querySelector('select').focus();}
function addGameStatsMember(select){if(!select.value)return;const row=[...select.form.querySelectorAll('[data-score-member]')].find(r=>r.dataset.scoreMember===select.value);if(!row)return;row.hidden=false;row.querySelector('[name="included"]').checked=true;select.selectedOptions[0].remove();select.value='';select.closest('[data-score-add]').hidden=true;row.scrollIntoView({block:'start',behavior:'smooth'});row.querySelector('input[name^="number_"]').focus({preventScroll:true});}
async function saveGameStats(ev,id){ev.preventDefault();const f=new FormData(ev.target),entries=f.getAll('included').map(uid=>Object.fromEntries([['user_id',uid],['number',f.get('number_'+uid)],['participation',f.get('participation_'+uid)],['starter',f.has('starter_'+uid)],...scoreFields.map(([key])=>[key,f.get(key+'_'+uid)])]));await submit(ev,'game_stats',{result_id:id,visibility:f.get('visibility'),entries},'個人記録とExcelを更新しました。');}
let announcementFilter='';
function announcementList(){const items=(data.portal?.items||[]).filter(x=>x.kind==='announcements');return `<p class="hint">「内容を確認」で確認すると、同じ家庭の兄弟も確認済みになります。</p><div class="stack">${items.map(x=>{const r=data.announcement_reads?.find(r=>r.item_id===x.id&&r.user_id===user.id);return `<article class="card"><span class="tag ${!r?.read_at?'warn':''}">${esc(r?.status||'未読')}</span><h2>${esc(x.title)} ${articleNew('announcements',x.id)}</h2>${r?.read_at?`<p class="hint">${esc(r.reader_name)} さんが確認：${esc(r.read_at)}</p>`:''}<button class="outline" onclick="openAnnouncement('${x.id}')">内容を確認</button></article>`;}).join('')||'<div class="card">お知らせはありません。</div>'}</div>`;}
async function openAnnouncement(id){const item=data.portal.items.find(x=>x.id===id),r=data.announcement_reads.find(x=>x.item_id===id&&x.user_id===user.id);modal(item.title,`<p class="service-text">${esc(item.body)}</p>${announcementAttachments(id)}${user.role==='member'?'<p class="hint" id="notice-read-status">確認状況を保存中…</p>':''}`);if(user.role!=='member')return;try{await api('announcement_read',{id,revision:r.revision});data=await api('data');dashboard();$('#notice-read-status').textContent='この家庭で確認済みとして記録しました。';}catch(e){$('#notice-read-status').textContent=e.message;}}
function announcementReadPanel(id){const rows=(data.announcement_reads||[]).filter(r=>r.item_id===id),read=rows.filter(r=>r.read_at).length;return `<details class="publication-read-panel"><summary>既読・未読一覧（既読 ${read}人 ／ 未読 ${rows.length-read}人）</summary><p class="hint">既読は内容を開いた記録です。兄弟の確認を含みます。本文更新後は未読に戻ります。</p>${[true,false].map(done=>{const group=rows.filter(r=>!!r.read_at===done);return `<section><h4>${done?'既読者':'未読者'}（${group.length}人）</h4>${group.map(r=>`<p><b>${esc(r.name)}</b>${done?`<br><span class="hint">${esc(r.status)} ／ ${esc(r.reader_name||'—')} ／ ${esc(r.read_at)}</span>`:''}</p>`).join('')||'<p class="hint">該当者はいません。</p>'}</section>`;}).join('')}</details>`;}

function surveyConfigFields(id){const f=data.surveys?.forms.find(x=>x.item_id===id);return `<div class="survey-builder">${selectField('アンケート形式','survey_type',[['text','自由記入'],['camp','合宿（見守り・配膳）'],['lunch','お弁当注文']],f?.kind||'text').replace('<select','<select onchange="updateSurveyBuilder(this.form)"')}${field('回答期限（日本時間）','deadline',f?.deadline||'','datetime-local')}<p data-camp-guide ${f?.kind==='camp'?'':'hidden'} class="hint">保護者見守り・配膳の可否と、一部可能な場合の時間帯を自動で質問します。</p><label class="field" data-lunch-builder ${f?.kind==='lunch'?'':'hidden'}>お弁当メニュー<textarea name="menu_lines" placeholder="からあげ弁当|600">${esc((f?.menus?.length?f.menus:[{name:'からあげ弁当',price:600}]).map(m=>m.name+'|'+m.price).join('\n'))}</textarea><span class="hint">1行に1種類、「メニュー名|税込金額」で入力します。</span></label></div>`;}
function updateSurveyBuilder(form){const camp=form.elements.survey_type.value==='camp';form.querySelector('[data-camp-guide]').hidden=!camp;form.querySelector('[data-lunch-builder]').hidden=form.elements.survey_type.value!=='lunch';if(camp&&!form.elements.title.value)form.elements.title.value='合宿の見守り・配膳アンケート';if(camp&&!form.elements.body.value)form.elements.body.value='合宿での保護者見守り・配膳へのご協力について回答してください。';}
function surveyAnswerContent(id){if(surveyClosed(id))return surveyDeadline(id)+`<p class="survey-closed" role="status">${surveyClosedMessage}</p>${surveyReviewButton(id)}`;return (data.portal?.items||[]).filter(x=>x.kind==='surveys'&&x.id===id).map(x=>{const f=data.surveys?.forms.find(f=>f.item_id===x.id),a=data.surveys?.answers.find(a=>a.item_id===x.id&&a.user_id===user.id);return `<article class="card parent-survey-card"><span class="tag">${a?'回答済み':'アンケート'}</span><h2>${esc(x.title)} ${articleNew('surveys',x.id)}</h2>${surveyDeadline(x.id)}<p class="service-text">${esc(x.body)}</p>${f?.kind==='lunch'?`<form onsubmit="saveLunch(event,'${x.id}')" data-lunch="${x.id}">${selectField('1. お弁当を注文しますか','order',[['','選択してください'],'はい','いいえ'],a?.order||'').replace('<select','<select onchange="updateLunch(this.form)"')}<div class="lunch-options" ${a?.order==='はい'?'':'hidden'}>${selectField('2. 注文する方','who',[['','選択してください'],'子供のみ','保護者のみ','両方'],a?.who||'').replace('<select','<select onchange="updateLunch(this.form)"')}${['子供','保護者'].map((g,i)=>`<div data-meal-group="${g}" ${a?.meals.some(m=>m.group===g)?'':'hidden'}><label class="field">3. ${g}の個数<input type="number" name="count${i}" min="1" max="20" value="${a?.meals.filter(m=>m.group===g).length||1}" oninput="updateLunch(this.form)"></label><div class="meal-selects">${a?.meals.filter(m=>m.group===g).map((m,j)=>lunchMenu(f,g,j,f.menus.findIndex(v=>v.name===m.name))).join('')||''}</div></div>`).join('')}<p class="lunch-total">合計：¥${(a?.total||0).toLocaleString()}</p></div><p class="hint">回答は選択中の会員名で保存します。同じ注文を兄弟それぞれで重複して送らないようご注意ください。回答で決済・業者への発注は行われません。</p><div class="error" role="alert"></div><button class="lime">${a?'回答を更新':'回答を送信'}</button></form>`:f?.kind==='camp'?campSurveyForm(x.id):serviceForm('surveys',x.id)}</article>`;}).join('')||'<div class="card">現在、アンケートはありません。</div>';}
function lunchMenu(f,g,j,value=''){return `<label class="field">4. ${g} ${j+1}個目のメニュー<select name="meal_${g}_${j}" required onchange="lunchTotal(this.form)"><option value="">選択してください</option>${f.menus.map((m,i)=>`<option value="${i}" ${String(value)===String(i)?'selected':''}>${esc(m.name)} ／ ¥${m.price.toLocaleString()}</option>`).join('')}</select></label>`;}
function updateLunch(form){const f=data.surveys.forms.find(x=>x.item_id===form.dataset.lunch),yes=form.elements.order.value==='はい',who=form.elements.who.value;form.querySelector('.lunch-options').hidden=!yes;form.elements.who.required=yes;form.elements.who.disabled=!yes;form.querySelectorAll('[data-meal-group]').forEach(box=>{const g=box.dataset.mealGroup,show=yes&&(who==='両方'||who===g+'のみ'),input=box.querySelector('input'),area=box.querySelector('.meal-selects'),values=[...area.querySelectorAll('select')].map(s=>s.value);box.hidden=!show;input.disabled=!show;input.required=show;const n=Math.max(0,Math.min(20,Number(input.value)||0));area.innerHTML=show?Array.from({length:n},(_,j)=>lunchMenu(f,g,j,values[j]??'')).join(''):'';});lunchTotal(form);}
function lunchTotal(form){const f=data.surveys.forms.find(x=>x.item_id===form.dataset.lunch);let total=0;form.querySelectorAll('.meal-selects select').forEach(s=>{if(s.value!=='')total+=f.menus[Number(s.value)]?.price||0;});form.querySelector('.lunch-total').textContent='合計：¥'+total.toLocaleString();}
async function saveLunch(ev,id){ev.preventDefault();const form=ev.target,f=data.surveys.forms.find(x=>x.item_id===id),meals=[];form.querySelectorAll('[data-meal-group]:not([hidden])').forEach(box=>box.querySelectorAll('select').forEach(s=>meals.push({group:box.dataset.mealGroup,menu:Number(s.value)})));await submit(ev,'lunch_answer',{item_id:id,revision:f.revision,order:form.elements.order.value,who:form.elements.who.value,meals},'アンケートを保存しました。');}
function lunchCoachSummary(id=''){return (data.surveys?.forms||[]).filter(f=>f.kind==='lunch'&&(!id||f.item_id===id)).map(f=>{const answers=(data.surveys.answers||[]).filter(a=>a.item_id===f.item_id).sort((a,b)=>String(b.updated||'').localeCompare(String(a.updated||''))),meals=answers.flatMap(a=>a.meals);return `<section class="card"><h2>${esc(f.title)}：回答一覧</h2><div class="toolbar"><button class="lime" onclick="downloadLunch('${f.item_id}','csv')">CSVをダウンロード</button><button class="outline" onclick="downloadLunch('${f.item_id}','pdf')">PDFをダウンロード</button></div><p>回答 ${answers.length}名 ／ 注文 ${answers.filter(a=>a.order==='はい').length}名 ／ 合計 ${meals.length}個・¥${meals.reduce((s,m)=>s+m.price,0).toLocaleString()}</p>${lunchMenuTotalsTable(f.item_id)}<h3>家庭ごとの合計</h3>${lunchFamilies(f.item_id).map(g=>`<p><b>${esc(g.label)}</b>：${g.quantity}個 ／ ¥${lunchMoney(g.total)}</p>`).join('')}${answers.map(a=>`<details><summary>${esc(a.name)}：${esc(a.order)} ${a.meals.length}個 ／ ¥${a.total.toLocaleString()}</summary><p>${a.meals.map(m=>esc(m.group+'：'+m.name+' ¥'+m.price)).join('<br>')||'注文なし'}</p><p class="hint">${esc(a.updated)}</p></details>`).join('')||'<p>まだ回答はありません。</p>'}</section>`;}).join('');}

let pendingStatsImport=null;
function statsImportForm(){pendingStatsImport=null;modal('Excel・CSVから個人記録を取り込む',`<form onsubmit="previewStatsImport(event)"><p>管理Excelの「個人試合記録」シートを編集して選択してください。CSVは同じ見出し・列順のUTF-8形式に対応します。試合ID・会員IDで照合し、ファイルにない選手は残します。</p><p class="hint">対象試合は下書きに戻ります。取り込み後に記録を修正し、公開範囲を設定してください。画像・PDFの自動読み取りはまだ未対応です。</p><label class="field">ファイル<input type="file" name="statsfile" multiple accept=".xlsx,.csv" required></label><div class="error" role="alert"></div><button class="lime">取り込み内容を確認</button></form><div id="stats-import-preview"></div>`);}
async function previewStatsImport(ev){ev.preventDefault();ev.submitter.disabled=true;pendingStatsImport=[];try{const files=[...ev.target.elements.statsfile.files];if(!files.length||files.length>30)throw Error('ファイルは1〜30件選択してください。');const previews=[];for(const file of files){if(file.size>5*1024*1024)throw Error('1件5MB以下にしてください。');const content=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(file);});const request={filename:file.name,content},p=await api('game_stats_import',request);pendingStatsImport.push(request);previews.push(`<h3>${esc(file.name)}：${p.games}試合・${p.players}件</h3><div class="table-wrap"><table><thead><tr><th>試合ID</th><th>会員ID</th>${scoreFields.map(([,v])=>`<th>${v}</th>`).join('')}</tr></thead><tbody>${p.preview.map(r=>`<tr><td>${esc(r.result_id)}</td><td>${esc(r.user_id)}</td>${scoreFields.map(([k])=>`<td>${esc(r[k]||'—')}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`);}$('#stats-import-preview').innerHTML=previews.join('')+'<p class="hint">同じ試合・会員の記録が複数ある場合は、後のファイルを優先します。</p><button class="lime" onclick="confirmStatsImport(this)">確認した内容を下書きとして保存</button>';}catch(e){pendingStatsImport=null;$('#stats-import-preview').innerHTML='';ev.target.querySelector('.error').textContent=e.message;}finally{ev.submitter.disabled=false;}}
async function confirmStatsImport(button){if(!pendingStatsImport)return;button.disabled=true;try{while(pendingStatsImport.length){await api('game_stats_import',{...pendingStatsImport[0],confirm:true});pendingStatsImport.shift();data=await api('data');$('#modal').dataset.editToken=data.edit_token||'';}pendingStatsImport=null;$('#modal').close();await refresh();toast('下書きとして取り込みました。');}catch(e){toast('残りのファイルを再試行できます：'+e.message);button.disabled=false;}}
function newItems(section){
 if(section==='schedule')return (data.events||[]).filter(e=>e.kind!=='体験会').map(e=>({id:e.id,value:[e,(data.scheduling?.rosters||[]).find(r=>r.event_id===e.id),activityBrief(e.id)]}));
 if(section==='results')return (data.results||[]).map(r=>({id:r.id,value:[r,(data.game_stats?.rows||[]).filter(s=>s.result_id===r.id)]}));
 if(['surveys','announcements'].includes(section))return (data.portal?.items||[]).filter(x=>x.kind===section).map(x=>({id:x.id,value:[x,section==='surveys'?data.surveys?.forms.find(f=>f.item_id===x.id):null]}));
 if(['messages','board'].includes(section))return (data.portal?.entries||[]).filter(x=>x.kind===section&&(x.user_id!==user.id||x.status==='確認済み')).map(x=>({id:x.id,value:x}));
 return [];
}
function newItemKey(section,item){let hash=2166136261;for(const ch of JSON.stringify(item.value))hash=Math.imul(hash^ch.charCodeAt(0),16777619);return section+':'+item.id+':'+(hash>>>0).toString(16);}
function isNewItem(section,item){if(section==='board'&&user.role==='member')return !(data.board_reads||[]).find(r=>r.item_id===item.id&&r.user_id===user.id)?.read_at;if(section==='announcements'&&user.role==='member')return !(data.announcement_reads||[]).find(r=>r.item_id===item.id&&r.user_id===user.id)?.read_at;return !(data.new_seen||[]).includes(newItemKey(section,item));}
function newCount(section){if(section==='dashboard')return ['schedule','announcements','results','surveys','messages','board'].reduce((n,s)=>n+newCount(s),0);return newItems(section).filter(x=>isNewItem(section,x)).length;}
function navNew(section){const n=newCount(section);return n?`<span class="new-badge" aria-label="新着${n}件">NEW</span>`:'';}
function articleNew(section,id){const item=newItems(section).find(x=>x.id===id);if(!item||!isNewItem(section,item))return '';return `<span class="new-badge" data-new-section="${section}" data-new-id="${esc(id)}">NEW</span>`;}
let newReadObserver=null,newReadTimers=[];
function observeNewArticles(){if(newReadObserver)newReadObserver.disconnect();newReadTimers.forEach(clearTimeout);newReadTimers=[];const owner=user?.id;if(!owner)return;const seenPending=new Set();newReadObserver=new IntersectionObserver(entries=>{for(const e of entries){const card=e.target;if(!e.isIntersecting||e.intersectionRect.height<Math.min(100,card.getBoundingClientRect().height/2)||seenPending.has(card))continue;seenPending.add(card);newReadTimers.push(setTimeout(async()=>{seenPending.delete(card);if(user?.id!==owner||!card.isConnected||document.hidden)return;const box=card.getBoundingClientRect();if(Math.min(box.bottom,innerHeight)-Math.max(box.top,0)<Math.min(100,box.height/2))return;const badges=[...card.querySelectorAll('[data-new-section]')].filter(b=>b.dataset.newSection!=='announcements'),keys=badges.map(b=>{const item=newItems(b.dataset.newSection).find(x=>x.id===b.dataset.newId);return item?newItemKey(b.dataset.newSection,item):null;}).filter(Boolean);if(!keys.length)return;try{await api('new_seen',{keys});if(user?.id!==owner)return;data.new_seen=[...new Set([...(data.new_seen||[]),...keys])];document.querySelectorAll('[data-new-section]').forEach(b=>{const item=newItems(b.dataset.newSection).find(x=>x.id===b.dataset.newId);if(item&&keys.includes(newItemKey(b.dataset.newSection,item)))b.remove();});document.querySelectorAll('[data-new-nav]').forEach(el=>el.innerHTML=navNew(el.dataset.newNav));document.querySelectorAll('.mobile-route option').forEach(el=>{el.textContent=el.textContent.replace(/ NEW$/,'')+(newCount(el.value)?' NEW':'');});}catch{}} ,900));}}, {threshold:[0,.1,.25,.5,.75,1]});document.querySelectorAll('[data-new-section]').forEach(b=>{if(['announcements','board'].includes(b.dataset.newSection))return;if(b.dataset.newSection==='schedule')return;const card=b.closest('article');if(card)newReadObserver.observe(card);});}

let resultsMonth=new Date(new Date().getFullYear(),new Date().getMonth(),1),selectedResult='',resultsCategory='';
function categoryResults(){return (data.results||[]).filter(r=>!resultsCategory||(r.group_name||'').split(/[、,]/).map(x=>x.trim()).includes(resultsCategory));}
function resultsForDate(){return selectedResult?categoryResults().filter(r=>r.id===selectedResult):[];}
function changeResultsMonth(n){resultsMonth=new Date(resultsMonth.getFullYear(),resultsMonth.getMonth()+n,1);selectedResult='';dashboard();}
function chooseResult(id){selectedResult=id;dashboard();document.getElementById('selected-results')?.scrollIntoView({behavior:'smooth',block:'start'});}
function resultsCalendar(){const y=resultsMonth.getFullYear(),m=resultsMonth.getMonth(),prefix=y+'-'+String(m+1).padStart(2,'0'),start=new Date(y,m,1).getDay(),days=new Date(y,m+1,0).getDate();return `<section class="results-calendar-section"><div class="card"><label class="field">表示するカテゴリー<select onchange="resultsCategory=this.value;selectedResult='';dashboard()">${[['','すべて'],...['男子A','男子B','女子U９','女子U12','U15アドバンス','U15ベーシック'].map(x=>[x,x])].map(([v,label])=>`<option value="${v}" ${resultsCategory===v?'selected':''}>${label}</option>`).join('')}</select></label></div><div class="toolbar month-toolbar"><button class="outline small" aria-label="試合カレンダーの前月" onclick="changeResultsMonth(-1)">前月</button><h2>${y}年 ${m+1}月</h2><button class="outline small" aria-label="試合カレンダーの翌月" onclick="changeResultsMonth(1)">翌月</button></div><p class="hint">試合名を押すと、その試合の結果・動画・個人記録を表示します。</p><div class="month-scroll"><div class="attendance-calendar results-calendar">${['日','月','火','水','木','金','土'].map(d=>`<div class="calendar-weekday">${d}</div>`).join('')}${'<div class="calendar-blank"></div>'.repeat(start)}${Array.from({length:days},(_,i)=>{const date=prefix+'-'+String(i+1).padStart(2,'0');return `<div class="calendar-date"><b>${i+1}</b>${categoryResults().filter(r=>r.date===date).map(r=>`<button class="result-calendar-game ${selectedResult===r.id?'selected':''}" aria-label="${esc(r.date+' '+(r.title||'vs '+r.opponent))}の結果を表示" onclick="chooseResult('${r.id}')"><span>${esc(r.title||'vs '+r.opponent)}</span><small>${esc(r.group_name)}</small>${newCount('results')&&newItems('results').some(x=>x.id===r.id&&isNewItem('results',x))?`<small class="new-badge" data-new-section="results" data-new-id="${esc(r.id)}">NEW</small>`:''}</button>`).join('')}</div>`;}).join('')}</div></div>${!categoryResults().some(r=>r.date.startsWith(prefix))?'<p class="hint">この月・カテゴリーに登録された試合はありません。</p>':''}</section>`;}
function feeAdjustmentsPanel(){if(data.billing_plan)return '';if(user.role!=='admin')return '';const periods=data.fee_adjustment_periods||{},members=(data.users||[]).filter(u=>u.role==='member'&&u.active),families=[...new Set(members.map(u=>u.family_id).filter(Boolean))];return `<section class="card payment-preferences"><h2>今回・次回の金額設定／途中入会</h2><p>通常金額と異なる会費を、会員別またはご家庭全体で設定できます。途中入会の初回金額は「今回の請求」「この期間だけ」を選び、確定した金額を入力してください。</p><form onsubmit="saveFeeAdjustment(event)">${selectField('対象','target_key',members.map(u=>['会員|'+u.id,'会員：'+u.name]).concat(families.map(f=>['家庭|'+f,'家庭：'+members.filter(u=>u.family_id===f).map(u=>u.name).join('・')])),'')}${selectField('いつの請求に適用するか','apply',[['current','今回の請求（'+periods.current+'開始）'],['next','次回の請求（'+periods.next+'開始）']],'current')}${selectField('適用する範囲','scope',[['once','この期間だけ（途中入会の初回など）'],['ongoing','この期間以降も同じ金額']],'once')}<label class="field">お支払い金額（税込・円）<input type="number" name="amount" min="0" max="10000000" step="1" required></label><label class="field">設定理由（任意）<input name="note" maxlength="300" placeholder="例：10月途中入会のため、初回のみ調整"></label><p class="hint">日割り・月割りは自動計算しません。家庭別合計額が設定されている場合は、会員別金額より家庭別合計額を優先します。同じ対象・開始月を保存すると設定を更新します。手続き済みの期間は変更できません。</p><div class="error" role="alert"></div><button class="lime">適用時期と金額を保存</button></form><h3>登録済みの金額設定</h3><div class="table-wrap"><table><thead><tr><th>対象</th><th>適用開始月</th><th>範囲</th><th>金額</th><th>理由</th></tr></thead><tbody>${(data.fee_adjustments||[]).map(r=>`<tr><td>${esc(r.kind+'：'+(members.find(u=>u.id===r.target)?.name||r.target))}</td><td>${esc(r.start_month)}</td><td>${r.scope==='once'?'この期間だけ':'以降も適用'}</td><td>¥${r.amount.toLocaleString()}</td><td>${esc(r.note)}</td></tr>`).join('')}</tbody></table></div></section>`;}
async function saveFeeAdjustment(ev){ev.preventDefault();const d=Object.fromEntries(new FormData(ev.target)),[kind,target]=d.target_key.split('|');await submit(ev,'fee_adjustment',{...d,kind,target,expected_start:data.fee_adjustment_periods[d.apply]},'適用時期と金額を保存しました。');}
const billingCategories=['年長','小学1年生〜3年生','小学4年生〜6年生','中学1年生〜3年生A','中学1年生〜3年生B'];
let pendingBillingPlan=null,billingIndividualMember='';
function filterBillingMember(value,inline=false){billingIndividualMember=value;const form=document.getElementById('billing-plan-form');if(!inline)form.querySelectorAll('[data-billing-shared]').forEach(el=>el.hidden=value!=='all');form.querySelectorAll('[data-billing-member]').forEach(el=>el.hidden=value!=='all'&&el.dataset.billingMember!==value);form.querySelector('[data-billing-profiles]').open=true;}
function billingMoneyInput(label,name,value){return `<label class="field">${label}<input type="number" min="0" max="10000000" step="1" name="${name}" value="${value??''}" placeholder="未設定"></label>`;}
function billingIndividualPage(){return heading('会費の個別設定','会員を選んで、今回・次回の会費を個別に設定します。','<a class="btn outline" href="#billing-settings">一括設定に戻る</a>')+billingPlanPanel(true);}
function billingPlanPanel(individual=false){const p=data.billing_plan;const members=(data.users||[]).filter(u=>u.role==='member'&&u.active);if(!members.some(u=>u.id===billingIndividualMember))billingIndividualMember=members[0]?.id||'';if(!p)return '';if(user.role!=='admin')return '<div class="card"><h2>会費設定</h2><p>会費の編集は管理者が行います。</p></div>';return `<section class="card"><h2>${individual?'会員ごとの会費設定':'徴収期間・カテゴリー別会費'}</h2><p>4〜9月、10〜翌年3月の半年ごとに手動で切り替えます。年会費は「有」の選手でも4月開始の期間だけ加算します。</p><p class="hint">入会金と年会費は別項目です。会費用の区分と、練習日程の男子A・女子U９等の活動カテゴリーは別に設定します。金額の空欄は未設定、0は無料です。</p>${individual?`<label class="field">設定する会員<select onchange="filterBillingMember(this.value)">${members.map(u=>`<option value="${esc(u.id)}" ${u.id===billingIndividualMember?'selected':''}>${esc(u.name)}</option>`).join('')}</select></label><p class="hint">個別の期間会費を設定した場合は、一括設定のカテゴリー料金より優先します。空欄に戻すと共通料金で計算します。期間も会員ごとに指定できます。共通設定に戻す場合は「一括設定と同じ」を選んでください。</p>`:''}<form id="billing-plan-form" onsubmit="previewBillingPlan(event)"><div data-billing-shared ${individual?'hidden':''}><div class="billing-period-heading"><details style="flex:1;min-width:0"><summary><b>徴収期間設定</b></summary>${['今回','次回'].map(slot=>`<fieldset class="card"><legend>${slot}の請求</legend><div class="form-grid">${field('開始月',slot+'_start',p.periods[slot].start,'month')}${field('終了月',slot+'_end',p.periods[slot].end,'month')}</div></fieldset>`).join('')}</details></div><details><summary><b>カテゴリーごとの金額設定</b></summary><div class="stack">${p.rates.map((r,i)=>`<fieldset class="card"><legend>${esc(r.category)}</legend><div class="form-grid">${[['monthly','月会費（円）'],['entry','入会金（円）'],['annual','年会費（円）'],['insurance','スポーツ保険料（円）']].map(([k,label])=>billingMoneyInput(label,'rate_'+i+'_'+k,r[k])).join('')}</div>${billingNoteInput('rate_'+i+'_note',r.note)}</fieldset>`).join('')}</div></details></div><details data-billing-profiles class="${individual?'':'billing-individual-inline'}" ${individual?'open':''}><summary><b>${individual?'会員ごとの区分・追加費用・個別金額':'個別設定'}</b></summary>${!individual?`<label class="field">設定する会員<select onchange="filterBillingMember(this.value,true)">${members.map(u=>`<option value="${esc(u.id)}" ${u.id===billingIndividualMember?'selected':''}>${esc(u.name)}</option>`).join('')}</select></label>`:''}<p class="hint">途中入会の調整は「期間会費上書き」に今回分の金額を入力します。空欄なら選択カテゴリーの月会費×選択期間の月数で自動計算します。次回を自動料金に戻す場合は、次回の上書き金額を空欄にしてください。</p><div class="stack">${p.profiles.map((r,i)=>`<fieldset class="card" data-billing-member="${esc(r.user_id)}" ${r.user_id!==billingIndividualMember?'hidden':''}><legend data-period-title>${esc(r.slot+'：'+(r.period||p.periods[r.slot]).start+'〜'+(r.period||p.periods[r.slot]).end)}</legend>${r.slot==='今回'?`<p>在籍状況：${esc(members.find(m=>m.id===r.user_id)?.enrollment?.status||'在籍')}</p><button type="button" class="outline" data-id="${esc(r.user_id)}" onclick="enrollmentForm(this.dataset.id)">休会・会費請求の停止を設定</button>`:''}${billingIndividualPeriod(r,i,p)}${selectField('会費用カテゴリー','profile_'+i+'_category',billingCategories,r.category)}${billingMoneyInput('期間会費上書き（選択期間の合計・円／任意）','profile_'+i+'_override',r.override)}<div class="form-grid">${[['entry','入会金'],['annual','年会費（4月徴収のみ）'],['insurance','スポーツ保険']].map(([k,label])=>selectField(label,'profile_'+i+'_'+k,[['false','無'],['true','有']],String(r[k]))).join('')}</div>${billingNoteInput('profile_'+i+'_note',r.note)}</fieldset>`).join('')}</div></details>${refundAdminPanel()}<p class="hint billing-settings-note">「今回」の変更は未払いの表示に反映し、「次回」の変更は予定額に反映します。支払い済みの金額・内訳は当時の記録を保持します。旧「会費金額設定.xlsx」の自動取込より、この設定を優先します。</p><div class="error" role="alert"></div><button class="lime">変更内容・計算結果を確認</button></form><div ${individual?'hidden':''}><hr><h3>Excelで編集する</h3><p>最新Excelの「徴収期間」「カテゴリー料金」「会員別会費設定」を編集してアップロードします。カテゴリー・有無はExcelのプルダウンで選べます。「会費設定版」は変更しないでください。</p><p><a class="btn outline" href="/basketball-club/api/excel">最新の設定を含むExcelを保存</a></p><form onsubmit="previewBillingExcel(event)"><label class="field">編集したExcel<input name="file" type="file" accept=".xlsx" required></label><div class="error" role="alert"></div><button class="outline">Excelの変更内容を確認</button></form></div></section>`;}
function billingPlanPreviewRows(p){return p.profiles.map(r=>{const rate=p.rates.find(x=>x.category===r.category),period=r.period||p.periods[r.slot],months=(Number(period.end.slice(0,4))-Number(period.start.slice(0,4)))*12+Number(period.end.slice(5))-Number(period.start.slice(5))+1,base=r.override??(rate.monthly==null?null:rate.monthly*months),parts=[['会費',base]];for(const [k,label] of [['entry','入会金'],['annual','年会費'],['insurance','スポーツ保険']])if(r[k]&&(k!=='annual'||period.start.endsWith('-04')))parts.push([label,rate[k]]);return {r,period,parts,total:parts.every(x=>x[1]!=null)?parts.reduce((n,x)=>n+x[1],0):null};});}
function showBillingPreview(p){pendingBillingPlan=p;const rows=billingPlanPreviewRows(p),money=v=>'¥'+v.toLocaleString('ja-JP'),totals=slot=>{const list=rows.filter(x=>!slot||x.r.slot===slot);return {sum:list.reduce((n,x)=>n+(x.total??0),0),unknown:list.filter(x=>x.total==null).length};},overall=totals();modal('会費設定の確認',`<p>今回・次回の設定をまとめて保存します。実際の請求・決済は行いません。</p><div class="billing-preview-tabs" role="group" aria-label="確認する期間">${['今回','次回'].map(slot=>`<button type="button" class="${slot==='今回'?'lime':'outline'}" data-preview-tab="${slot}" aria-pressed="${slot==='今回'}" onclick="switchBillingPreview('${slot}')">${slot}を表示</button>`).join('')}</div>${['今回','次回'].map(slot=>`<section data-preview-slot="${slot}" ${slot==='次回'?'hidden':''}><h3>${slot}：${esc(p.periods[slot].start+'〜'+p.periods[slot].end)}</h3>${rows.filter(x=>x.r.slot===slot).map(({r,period,parts,total})=>`<div class="card"><h3>${esc(r.name)}</h3><p>${esc(period.start+'〜'+period.end+' ／ '+r.category)}</p>${r.note?`<p>備考：${esc(r.note)}</p>`:''}${parts.map(([name,v])=>`<div class="info-row"><span>${name}</span><b>${v==null?'未設定':money(v)}</b></div>`).join('')}<p>合計：<strong>${total==null?'未設定の費用があります':money(total)}</strong></p></div>`).join('')||'<p class="hint">対象の会員はいません。</p>'}</section>`).join('')}<p class="hint">未設定の費用を含む会員は、金額確定まで支払い手続きを進められません。</p><section class="billing-preview-total"><h3>全体の徴収会費合計</h3>${['今回','次回'].map(slot=>{const t=totals(slot);return `<div class="info-row"><span>${slot}の合計${t.unknown?'（金額確定分）':''}</span><b>${money(t.sum)}</b></div>${t.unknown?`<p class="hint">${slot}：金額未確定 ${t.unknown}件は合計に含みません。</p>`:''}`;}).join('')}<div class="billing-preview-grand"><span>今回＋次回${overall.unknown?'（金額確定分）':''}</span><strong>${money(overall.sum)}</strong></div><p class="hint">入会金・年会費・スポーツ保険料を含む徴収予定額です。</p></section><button class="lime" onclick="confirmBillingPlan(this)">この設定を保存</button>`);}
function switchBillingPreview(slot){if(!['今回','次回'].includes(slot))return;document.querySelectorAll('#modal [data-preview-slot]').forEach(el=>el.hidden=el.dataset.previewSlot!==slot);document.querySelectorAll('#modal [data-preview-tab]').forEach(el=>{const selected=el.dataset.previewTab===slot;el.className=selected?'lime':'outline';el.setAttribute('aria-pressed',String(selected));});}

async function previewBillingPlan(ev){ev.preventDefault();const f=new FormData(ev.target),old=data.billing_plan,p={revision:old.revision,periods:Object.fromEntries(['今回','次回'].map(s=>[s,{start:f.get(s+'_start'),end:f.get(s+'_end')}])),rates:old.rates.map((r,i)=>({category:r.category,note:f.get('rate_'+i+'_note')||'',...Object.fromEntries(['monthly','entry','annual','insurance'].map(k=>[k,f.get('rate_'+i+'_'+k)]))})),profiles:old.profiles.map((r,i)=>({...r,note:f.get('profile_'+i+'_note')||'',period:f.get('profile_'+i+'_period_mode')==='individual'?{start:f.get('profile_'+i+'_start'),end:f.get('profile_'+i+'_end')}:null,category:f.get('profile_'+i+'_category'),override:f.get('profile_'+i+'_override'),...Object.fromEntries(['entry','annual','insurance'].map(k=>[k,f.get('profile_'+i+'_'+k)==='true']))}))};try{showBillingPreview((await api('billing_plan',p)).plan);}catch(e){ev.target.querySelector('.error').textContent=e.message;}}
async function previewBillingExcel(ev){ev.preventDefault();try{const file=ev.target.elements.file.files[0];if(file.size>5*1024*1024)throw Error('5MB以下のExcelを選んでください。');const content=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(file);});showBillingPreview((await api('billing_plan_import',{content})).plan);}catch(e){ev.target.querySelector('.error').textContent=e.message;}}
async function confirmBillingPlan(button){if(!pendingBillingPlan)return;button.disabled=true;try{await api('billing_plan',{...pendingBillingPlan,confirm:true});pendingBillingPlan=null;$('#modal').close();await refresh();toast('会費設定とExcelを更新しました。');}catch(e){toast(e.message);button.disabled=false;}}

function resultHistoryLinks(staff){return `<section class="card result-history-links"><h2>これまでの記録</h2><div class="result-action-links"><a class="btn lime" href="#personal-history">個人のこれまでの記録</a><a class="btn scorecard-button" href="#team-history">チーム全体の過去の履歴</a></div></section>`;}
let coachHistoryMember='';
function personalHistoryRows(memberId=user.id){
 const demoIds=['sample-result-sep05','sample-result-sep06','sample-result-sep12','r1'];
 return [...(data.results||[])].sort((a,b)=>b.date.localeCompare(a.date)||a.id.localeCompare(b.id)).map(result=>{
  const stored=(data.game_stats?.rows||[]).find(r=>r.result_id===result.id&&r.user_id===memberId),publication=data.game_stats?.publications.find(p=>p.result_id===result.id),i=demoIds.indexOf(result.id);
  if(stored)return {result,record:stored,sample:false};
  if(!publication&&['member01','member02'].includes(memberId)&&i>=0){const other=memberId==='member02';return {result,sample:true,record:{points:(other?[4,6,8,10]:[6,8,12,10])[i],rebounds:[3,4,6,5][i],assists:(other?[2,3,3,5]:[1,2,4,3])[i],steals:[1,2,2,3][i],blocks:[0,0,1,1][i],fouls:[2,1,2,1][i],turnovers:[3,2,2,1][i],participation:'出場'}};}
  return {result,record:null,sample:false};
 }).filter(row=>row.record!==null);
}
function personalPerformanceChart(rows,name){
 const played=rows.filter(r=>r.record&&!String(r.record.participation||'').includes('出場なし'));
 const fields=[['points','得点','点','シュートで得点につなげた記録'],['rebounds','リバウンド','回','シュート後のボールを取った記録'],['assists','アシスト','回','味方の得点につながるパスの記録'],['steals','スティール','回','相手からボールを奪った記録'],['blocks','ブロック','回','相手のシュートを防いだ記録']];
 const values=fields.map(([key,label,unit,help])=>{const records=played.filter(r=>typeof r.record[key]==='number'&&Number.isFinite(r.record[key]));return {key,label,unit,help,count:records.length,average:records.length?records.reduce((sum,r)=>sum+r.record[key],0)/records.length:null};});
 if(!values.some(v=>v.count))return '<section class="card personal-performance"><h2>プレーの特徴</h2><p class="hint">出場した試合の記録が登録されると、棒グラフで表示します。</p></section>';
 const maximum=Math.max(1,...values.map(v=>v.average||0)),axis=Math.ceil(maximum/5)*5;
 return `<section class="card personal-performance"><h2>プレーの特徴</h2><p>${esc(name)}さんの1試合あたりの平均</p><p class="hint">得点・ボールの獲得・味方へのパスなど、プレーの特徴を見つける参考にしてください。棒の長さは記録の平均値で、能力の評価点ではありません。</p><div class="performance-axis" aria-hidden="true"><span>0</span><span>${axis/2}</span><span>${axis}</span></div><div class="performance-bars">${values.map(v=>`<div class="performance-row"><div class="performance-label"><b>${v.label}</b><small>${v.count}試合</small></div><div class="performance-track" role="img" aria-label="${esc(v.label)}：${v.average==null?'未記録':v.average.toFixed(1)+v.unit+'／試合'}"><div class="performance-fill" style="width:${v.average==null?0:v.average/axis*100}%"></div></div><strong>${v.average==null?'—':v.average.toFixed(1)}<small>${v.unit}</small></strong><p class="performance-help">${v.help}</p></div>`).join('')}</div><p class="hint">出場なしの試合は集計しません。未入力の項目は0として扱わず、その項目の平均から除外します。出場時間やポジションによって数値は変わります。</p>${rows.some(r=>r.sample)?'<p class="tag gray">仮の記録を含むデモグラフです</p>':''}</section>`;
}

function personalHistoryPage(){
 const staff=user.role!=='member',people=staff?(data.users||[]).filter(m=>m.role==='member'):[];if(staff&&!people.some(m=>m.id===coachHistoryMember))coachHistoryMember=people[0]?.id||'';const selected=staff?people.find(m=>m.id===coachHistoryMember):user;
 const rows=personalHistoryRows(selected?.id||''),recorded=rows.filter(r=>r.record),points=recorded.filter(r=>r.record.points!=null),average=points.length?(points.reduce((sum,r)=>sum+r.record.points,0)/points.length).toFixed(1):'—';
 const card=({result:r,record:s,sample})=>`<article class="card personal-match-record"><div class="toolbar"><b>${dateLabel(r.date)}</b><span class="tag">${esc(r.group_name)}</span>${sample?'<span class="tag gray">仮の記録</span>':''}</div><h3>vs ${esc(r.opponent)}</h3><p>チーム結果：${r.ours} - ${r.theirs}</p>${s?`<dl class="personal-record-metrics">${scoreFields.map(([key,label])=>`<div><dt>${label}</dt><dd>${s[key]??'—'}</dd></div>`).join('')}</dl>`:'<p class="hint">個人記録は未登録・未公開です。</p>'}<button class="outline small" onclick="openScorecard('${r.id}')">この試合のスコアシート</button></article>`;
 return heading('個人のこれまでの記録',esc(selected?.name||'選手未選択')+'さんの個人記録です。'+(staff?'選手名を選ぶと記録を切り替えられます。':'上部の「報告するお子さま」を切り替えると、表示する記録も変わります。'),'<a class="btn outline" href="#results">試合結果へ戻る</a>')+`${staff?`<div class="card"><label class="field">記録を表示する選手<select onchange="coachHistoryMember=this.value;dashboard()">${people.map(m=>`<option value="${esc(m.id)}" ${m.id===coachHistoryMember?'selected':''}>${esc(m.name)}（${esc(m.grade)}）</option>`).join('')}</select></label></div>`:''}${rows.some(r=>r.sample)?'<p class="hint">「仮の記録」はデモ用の架空データです。実際の記録とは異なります。</p>':''}`+stats([['記録のある試合',recorded.length,'試合'],['平均得点',average,'点'],['合計得点',points.length?points.reduce((sum,r)=>sum+r.record.points,0):'—','点']])+personalPerformanceChart(rows,selected?.name||'選手')+`<div class="stack personal-history-list">${rows.slice(0,3).map(card).join('')||'<p class="card">試合記録はまだありません。</p>'}</div>${rows.length>3?`<details class="condition-history-more"><summary><span class="when-closed">もっと見る（残り${rows.length-3}試合）</span><span class="when-open">閉じる（最新3試合）</span></summary><div class="stack">${rows.slice(3).map(card).join('')}</div></details>`:''}`;
}
let teamHistoryCategory='';
function teamHistoryPage(){const rows=(data.results||[]).filter(r=>!teamHistoryCategory||(r.group_name||'').split(/[、,]/).map(x=>x.trim()).includes(teamHistoryCategory)).slice().sort((a,b)=>b.date.localeCompare(a.date)||a.id.localeCompare(b.id)),wins=rows.filter(r=>r.ours>r.theirs).length,losses=rows.filter(r=>r.ours<r.theirs).length;return heading('チーム全体の過去の履歴','過去の試合結果とスコアシートをまとめて確認できます。','<a class="btn outline" href="#results">試合結果へ戻る</a>')+`<div class="card"><label class="field">表示するカテゴリー<select onchange="teamHistoryCategory=this.value;dashboard()">${[['','すべて'],...['男子A','男子B','女子U９','女子U12','U15アドバンス','U15ベーシック'].map(x=>[x,x])].map(([v,label])=>`<option value="${v}" ${teamHistoryCategory===v?'selected':''}>${label}</option>`).join('')}</select></label></div>`+stats([['掲載試合',rows.length,'試合'],['勝利',wins,'試合'],['敗戦',losses,'試合'],['引分',rows.length-wins-losses,'試合']])+`<div class="stack team-history-list">${rows.map(r=>`<article class="card"><div class="toolbar"><b>${dateLabel(r.date)}</b><span class="tag">${esc(r.group_name)}</span><span class="tag ${r.ours<r.theirs?'gray':''}">${r.ours>r.theirs?'勝利':r.ours<r.theirs?'敗戦':'引分'}</span>${user.role==='admin'?`<button type="button" class="lime result-edit-button" onclick="resultForm('${r.id}')">編集</button>`:''}</div><h3>vs ${esc(r.opponent)}</h3><div class="history-final-score"><b>CHEETAHS</b><strong>${r.ours} - ${r.theirs}</strong></div>${resultLinks(r)}</article>`).join('')||'<p class="card">選択したカテゴリーの試合結果はまだありません。</p>'}</div>`;}

const surveyClosedMessage='回答時間外です。直接コーチへご連絡お願いします';
function surveyClosed(id){const d=data.surveys?.forms.find(f=>f.item_id===id)?.deadline;return !!d&&Date.now()>=Date.parse(d+'+09:00');}
function surveyDeadline(id){const d=data.surveys?.forms.find(f=>f.item_id===id)?.deadline;return `<p class="survey-deadline ${surveyClosed(id)?'expired':''}">回答期限：${d?esc(d.replace('T',' '))+'（日本時間）':'期限なし'}${surveyClosed(id)?' ／ 受付終了':''}</p>`;}
function parentSurveys(){return (data.portal?.items||[]).filter(x=>x.kind==='surveys').map(x=>`<article class="card parent-survey-card"><h2><button class="survey-title" onclick="openSurvey('${x.id}')">${esc(x.title)}</button> ${articleNew('surveys',x.id)}</h2>${surveyDeadline(x.id)}<span class="tag ${surveyClosed(x.id)?'gray':''}">${surveyClosed(x.id)?'受付終了':'受付中'}</span>${surveyReviewButton(x.id)}<p class="hint">題名を押すとアンケート画面が開きます。</p></article>`).join('')||'<div class="card">現在、アンケートはありません。</div>';}
function openSurvey(id){modal('保護者アンケート',`<div data-open-survey="${id}">${surveyAnswerContent(id)}</div>`);}
setInterval(()=>{const box=document.querySelector('[data-open-survey]');if(box&&surveyClosed(box.dataset.openSurvey)&&box.querySelector('form'))box.innerHTML=surveyAnswerContent(box.dataset.openSurvey);},1000);

function ownSurveyAnswer(id){const lunch=data.surveys?.answers.find(a=>a.item_id===id&&a.user_id===user.id);if(lunch)return {kind:'lunch',answer:lunch};const text=(data.portal?.entries||[]).find(a=>a.kind==='surveys'&&a.item_id===id&&a.user_id===user.id);return text?{kind:'text',answer:text}:null;}
function surveyReviewButton(id){return ownSurveyAnswer(id)?`<div class="survey-review-action"><span class="tag">回答済み</span><button type="button" class="outline" onclick="openSurveyAnswer('${id}')">内容を確認する</button></div>`:'';}
function openSurveyAnswer(id){const saved=ownSurveyAnswer(id);if(!saved){toast('まだ回答していません。');return;}const a=saved.answer,item=(data.portal?.items||[]).find(x=>x.id===id);modal('回答した内容',`<h3>${esc(a.title||item?.title||'保護者アンケート')}</h3><p>回答者：${esc(a.name||user.name)}</p><p class="hint">最終回答日時：${esc(a.updated||a.created)}</p>${saved.kind==='lunch'?`<dl class="shop-summary"><dt>お弁当を注文しますか</dt><dd>${esc(a.order)}</dd>${a.order==='はい'?`<dt>注文する方</dt><dd>${esc(a.who)}</dd><dt>個数</dt><dd>${a.meals.length}個（子供 ${a.meals.filter(m=>m.group==='子供').length}個・保護者 ${a.meals.filter(m=>m.group==='保護者').length}個）</dd>`:''}</dl>${a.order==='はい'?`<h3>選択したメニュー</h3>${a.meals.map((m,i)=>`<p>${i+1}. ${esc(m.group)}：${esc(m.name)} ／ ¥${m.price.toLocaleString()}</p>`).join('')}<p><strong>合計：¥${a.total.toLocaleString()}</strong></p>`:''}`:`<p class="service-text">${esc(a.body)}</p>`}<p class="hint">送信済みの回答内容です。${surveyClosed(id)?'回答期限を過ぎているため変更できません。':''}</p><button type="button" class="outline" onclick="$('#modal').close()">閉じる</button>`);}

function boardList(){const staff=user.role!=='member',items=(data.portal?.entries||[]).filter(x=>x.kind==='board');return (!staff?'<p class="hint">「内容を確認」で確認すると、同じ家庭の兄弟も確認済みになります。</p>':'')+`<div class="stack">${items.map(x=>{const r=data.board_reads?.find(r=>r.item_id===x.id&&r.user_id===user.id);return `<article class="card"><div class="toolbar">${!staff?`<span class="tag ${!r?.read_at?'warn':''}">${esc(r?.status||'未読')}</span>`:''}<time class="hint">${esc(x.created)}</time><span class="hint">${esc(x.name)}</span></div><div class="notice-management-row"><h2>${esc(x.body.split('\n')[0])} ${articleNew('board',x.id)}</h2><div class="notice-management-actions"><button type="button" class="outline" onclick="openBoard('${x.id}')">内容を確認</button>${user.role==='admin'&&adminCan('board-admin',true)?`<button class="outline" onclick="boardEditForm('${x.id}')">編集</button><button class="outline" onclick="deleteBoard('${x.id}')">削除</button>`:''}</div>${staff?`<details class="publication-read-panel"><summary>既読・未読一覧</summary>${boardReadGroups(x.id)}</details>`:''}</div>${r?.read_at?`<p class="hint">${esc(r.reader_name)} さんが確認：${esc(r.read_at)}</p>`:''}</article>`;}).join('')||'<div class="card">掲示板の投稿はありません。</div>'}</div>`;}

async function openBoard(id){const item=data.portal.entries.find(x=>x.id===id&&x.kind==='board');if(!item)return;const title=item.body.split('\n')[0],body=item.body.split('\n').slice(1).join('\n').trim();modal(title,`<p class="hint">${esc(item.name)} ／ ${esc(item.created)}</p><p class="service-text">${esc(body)}</p>${boardFiles(id)}${user.role==='member'?'<p class="hint" id="board-read-status">確認状況を保存中…</p>':''}`);if(user.role!=='member')return;const owner=user.id,r=data.board_reads?.find(r=>r.item_id===id&&r.user_id===owner);try{await api('board_read',{id,revision:r?.revision});const fresh=await api('data');if(user.id!==owner)return;data=fresh;dashboard();const status=document.getElementById('board-read-status');if(status)status.textContent='この家庭で確認済みとして記録しました。';}catch(e){const status=document.getElementById('board-read-status');if(status)status.textContent=e.message;}}

function familyPaymentHistory(){const rows=data.family_billing?.history||[];return `<details class="injury-report-history payment-history"><summary><span class="history-show">支払い履歴を見る</span><span class="history-hide">支払い履歴を閉じる</span></summary><section class="injury-history-content"><h2>支払い履歴</h2><p class="hint">ご家庭全員分の履歴です。お子さまを切り替えても同じ内容が表示されます。</p>${rows.map(r=>`<article class="card"><h3>${esc(billingPeriodLabel(r))}</h3><p>手続き日時：${esc(r.updated)}</p>${(r.lines||[]).map(line=>`<div class="info-row"><span>${esc(line.name)}</span><b>¥${Number(line.amount||0).toLocaleString()}</b></div>`).join('')}<p>お支払い合計金額：<strong>¥${Number(r.total||0).toLocaleString()}</strong></p><p>支払い方法：${esc(r.method)}</p><span class="tag">${esc(r.status)}</span></article>`).join('')||'<div class="card empty">まだ支払い履歴はありません。</div>'}</section></details>`;}

function memberGuide(){
 const guides=[
 ['dashboard','ホーム',['これからの活動や最近の体調報告を確認できます。各メニューのボタンから、利用したい画面へ進んでください。','画面上部の「会員ページ」を押すと、いつでも会員ホームに戻れます。']],
 ['schedule','練習・日程・出欠・体調報告',['各日程の「体調を報告する」から、同じページ内で体調を入力・送信できます。ページ下部で体調報告の履歴も確認できます。','カレンダーで日程を確認し、各予定の日時・会場・活動区分を確認してください。報告済みと未回答はカレンダー上でも見分けられます。','出欠予定を選び、黄色の「この日の出欠を報告する」でその日だけ送信できます。複数の日を変更した場合は「変更した出欠をまとめて送信」を押してください。','欠席・遅刻・早退の場合は理由を入力してください。','「詳細を確認する」から、コーチが決めた参加メンバー・注意事項・添付資料を確認できます。地図や、カレンダー下の日程PDFリンクもご利用ください。']],
 ['results','試合結果・動画',['カレンダーの試合を押すと、その試合の結果だけが下に表示されます。別の日を選ぶと表示内容が切り替わります。','「動画を見る」で動画を開き、「スコアシートを見る」でその試合のチーム得点・クォーター別得点・選手の得点やファウルなどを確認できます。スタメンの選手名は青い太字で表示します。','「個人のこれまでの記録」「チーム全体の過去の履歴」から過去の記録を確認できます。「個人のこれまでの記録」は、上部の「報告するお子さま」で選択した人だけの記録を表示します。兄弟の名前を切り替えると、そのお子さまの記録・平均得点・合計得点に切り替わります。選択したお子さまの個人記録がない試合は一覧に表示されません。他の方が見ることはできません。']],
 ['announcements','クラブからのお知らせ',['一覧から「内容を確認」を押して本文を確認します。確認すると既読になり、その記事のNEWが消えます。','兄弟は、どちらかのお子さまの画面で確認すれば、もう一方も確認済みになります。']],
 ['surveys','保護者アンケート',['題名を押すと回答画面が開きます。題名付近の回答期限を確認し、期限内に送信してください。','お弁当アンケートでは、注文の有無・対象・個数を選び、個数に応じてメニューを選択して金額を確認します。','回答後は「内容を確認する」で送信した回答を確認できます。期限を過ぎると回答できないため、直接コーチへご連絡ください。']],
 ['payments','月謝支払い',['対象期間、お子さまごとの金額、お支払い合計金額を確認してください。支払い期間や金額は管理者が設定します。','支払い方法を選び「支払い方法を保存」を押した後、「支払い手続きへ進む」で内容を確認します。保存済みの支払い方法は変更できます。','支払いはご家庭単位です。兄弟を切り替えても請求内容は共通です。「支払い履歴を見る」から対象期間・金額・支払い方法を確認できます。']],
 ['shop','スクール内物販',['商品写真や金額を確認し、サイズ・種類と数量を選んで「カートに入れる」を押します。複数の商品を追加できます。','「カートを見る」で数量や内容を確認・修正し、「カートの商品をまとめて購入する」から注文確認と支払い手続きへ進みます。','カートでは数量変更や商品の削除ができます。注文確認画面で商品・サイズ・個数・合計金額を確認してから、支払い手続きへ進んでください。','「購入履歴を見る」で注文内容や支払い状況を確認できます。カートは選択中のお子さまごとに分かれます。']],
 ['messages','諸連絡',['当日の連絡は、できるだけ「諸連絡」からお願いします。集合への遅れ、送迎の変更、当日の相談などを、対象のお子さまを選んで入力してください。','送信内容は管理者・担当コーチの「諸連絡」で確認できます。LINE通知は現在未接続です。','「コーチに送信」を押すと、選んだお子さまの連絡として保存されます。他の会員には表示されません。','「報告履歴を見る」で、過去の送信内容・日時・確認状況を確認できます。コーチが管理画面の「確認済みにする」を押すと「コーチ確認済み」と確認日時が反映されます。LINEの既読だけでは確認済みにはなりません。','出欠予定そのものの変更は「練習・試合日程・出欠報告」でも更新してください。']],
 ['board','掲示板',['管理者・コーチが投稿した案内を確認する場所です。会員からの投稿はできません。','「内容を確認」で本文を確認します。同じ家庭の兄弟で既読が共有されます。個別の相談は「諸連絡」をご利用ください。']],
 ['injuries','怪我報告',['怪我報告は怪我をした際にご連絡お願いします。最初に報告するお子さまの名前を確認してください。','怪我をした日・部位を入力し、練習への参加を「見学」「一部参加を希望」「欠席」「コーチに相談」から選びます。','状況・受診状況・コーチへの連絡を入力して「コーチに送信」を押してください。本人とコーチが確認でき、他の会員には表示されません。','送信内容は管理者・担当コーチの「諸連絡」で確認できます。LINE通知は現在未接続です。','「報告履歴を見る」で、過去の報告内容・日時・確認状況を確認できます。コーチが管理画面の「確認済みにする」を押すと「コーチ確認済み」と確認日時が反映されます。欠席など出欠予定が変わる場合は、出欠報告も更新してください。']]
 ];
 return heading('会員ページの使い方','知りたいメニューを押すと、操作方法が開きます。')+`<details class="card member-guide-item"><summary>はじめに：報告するお子さまを確認</summary><p>兄弟でご利用の場合は、画面上部の「報告するお子さま」で名前を切り替えてください。出欠・体調・怪我などの報告は、選んだお子さまの記録になります。</p><p>スマホでは上部の「メニュー」を押して画面を切り替えます。赤いNEWは未確認の新着・更新の目印です。日程の詳細が更新されたときも、内容をご確認ください。</p><p>各履歴は最初は閉じています。「履歴を見る」のボタンで開き、もう一度押すと閉じます。</p></details><details class="card member-guide-item"><summary>当日の連絡について</summary><p><strong>当日の連絡は、できるだけ「諸連絡」または「怪我報告」からお願いします。</strong> 怪我については「怪我報告」、送迎の変更やその他の相談は「諸連絡」をご利用ください。</p><p>送信内容は管理者・担当コーチの「諸連絡」で確認できます。LINE通知は現在未接続です。</p><div class="toolbar"><a class="btn lime" href="#messages">諸連絡へ</a><a class="btn outline" href="#injuries">怪我報告へ</a></div></details><div class="member-guide-list">${guides.map(([id,title,steps])=>`<details class="card member-guide-item"><summary>${esc(title)}</summary><ol>${steps.map(step=>`<li>${esc(step)}</li>`).join('')}</ol><a class="btn outline" href="#${id}">${esc(title)}を開く</a></details>`).join('')}</div><p class="hint">このサイトは操作確認用のデモです。LINEへの通知は未接続です。月謝・物販の手続きで実際のお金は動きません。表示される動画・試合記録などにはサンプルが含まれます。</p>`;
}

function boardReadGroups(id){const rows=(data.board_reads||[]).filter(r=>r.item_id===id);return [true,false].map(read=>{const group=rows.filter(r=>!!r.read_at===read);return `<section class="board-read-group"><h3>${read?'既読者':'未読者'}（${group.length}人）</h3>${group.map(r=>`<p>${esc(r.name)}${read?' ／ '+esc(r.reader_name)+' ／ '+esc(r.read_at):''}</p>`).join('')||'<p class="hint">該当者はいません。</p>'}</section>`;}).join('');}
function boardFiles(id){return (data.portal?.files||[]).filter(f=>f.entry_id===id).map(f=>{const url='/basketball-club/api/board_attachment?id='+encodeURIComponent(f.id);return `<div class="board-file">${f.mime.startsWith('image/')?`<img src="${url}" alt="${esc(f.name)}" loading="lazy">`:''}<a href="${url}" target="_blank" rel="noopener">${esc(f.name)}を開く</a> ／ <a href="${url}&download=1">ダウンロード</a></div>`;}).join('');}

function publicationManager(kind){const canManage=user.role==='admin'&&adminCan(({surveys:'survey-admin',announcements:'announcement-admin',shop:'shop-admin'})[kind],true);const items=(data.portal?.items||[]).filter(x=>x.kind===kind);return `<section class="publication-manager">${kind==='announcements'?'':`<h3>${esc(serviceLabels[kind])}の掲載管理</h3>`}${canManage?`<p><button class="lime" onclick="portalItemForm('${kind}')">＋ ${kind==='shop'?'商品を新規登録':kind==='surveys'?'保護者アンケートを新規作成':'お知らせを新規作成'}</button></p>`:''}${items.map(x=>`<div class="info-row ${kind==='announcements'?'notice-management-row':''}"><b>${kind==='shop'?`<span aria-hidden="true">${shopIcon(x.title)}</span> `:''}${esc(kind==='shop'?shopTitle(x.title):x.title)}</b><div class="toolbar ${kind==='announcements'?'notice-management-actions':''}">${kind==='announcements'?`<button class="outline" onclick="openAnnouncement('${x.id}')">内容を確認</button>`:''}${kind==='surveys'?`<button class="lime" onclick="showSurveyResults('${x.id}')">結果を見る</button>`:''}${canManage?`<button class="outline" onclick="portalItemForm('${kind}','${x.id}')">編集</button><button class="outline" onclick="deletePortalItem('${x.id}')">削除</button>`:''}</div>${kind==='announcements'?announcementReadPanel(x.id):''}</div>`).join('')||'<p>まだ掲載されていません。</p>'}</section>`;}
function boardEditForm(id=''){const x=(data.portal?.entries||[]).find(x=>x.id===id),body=x?.body||'';modal(id?'掲示板を編集':'掲示板に新規投稿',`<form onsubmit="saveBoardEdit(event,'${id}')">${field('題名','title',body.split('\n')[0])}<label class="field">内容<textarea name="body" required maxlength="3000">${esc(body.split('\n').slice(1).join('\n').trim())}</textarea></label>${(data.portal?.files||[]).filter(f=>f.entry_id===id).map(f=>`<label class="check-row"><input name="keep" type="checkbox" value="${f.id}" checked>${esc(f.name)}を残す</label>`).join('')}<label class="field">写真・PDF・CSVを追加<input name="attachments" type="file" multiple accept=".jpg,.jpeg,.png,.webp,.pdf,.csv"></label><p class="hint">合計30件まで、1件5MB以下。編集すると未読に戻ります。</p><div class="error" role="alert"></div><button class="lime">保存して掲載</button></form>`);}
async function saveBoardEdit(ev,id){ev.preventDefault();try{const f=new FormData(ev.target),files=[...ev.target.elements.attachments.files],keep=f.getAll('keep'),uploads=[];if(keep.length+files.length>30)throw Error('添付は合計30件までです。');for(const file of files){if(file.size>5*1024*1024)throw Error('1件5MB以下にしてください。');uploads.push({name:file.name,content:await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(file);})});}await submit(ev,'portal',{action:'board_item',id,body:f.get('title')+'\n\n'+f.get('body'),keep_files:keep,uploads},'掲示板を保存しました。');}catch(e){ev.target.querySelector('.error').textContent=e.message;}}
async function deleteBoard(id){if(!confirm('この掲示板の投稿を削除しますか？'))return;try{await api('portal',{action:'board_delete',id});data=await api('data');dashboard();toast('削除しました。');}catch(e){toast(e.message);}}

function announcementAttachmentFields(id){return `<fieldset><legend>登録済みの添付（残すものにチェック）</legend>${(data.portal?.announcement_files||[]).filter(f=>f.entry_id===id).map(f=>`<label class="check-row"><input type="checkbox" name="notice_keep" value="${f.id}" checked>${esc(f.name)}</label>`).join('')||'<p class="hint">添付はありません。</p>'}</fieldset><label class="field">PDF・CSV・写真を追加<input type="file" name="notice_files" multiple accept=".pdf,.csv,.jpg,.jpeg,.png,.webp"></label><p class="hint">合計30件まで、1件5MB以下。添付の変更後は未読に戻ります。</p>`;}
function announcementAttachments(id){return (data.portal?.announcement_files||[]).filter(f=>f.entry_id===id).map(f=>{const url='/basketball-club/api/announcement_attachment?id='+encodeURIComponent(f.id);return `<div class="board-file">${f.mime.startsWith('image/')?`<img src="${url}" alt="${esc(f.name)}" loading="lazy">`:''}<a href="${url}" target="_blank" rel="noopener">${esc(f.name)}を開く</a> ／ <a href="${url}&download=1">ダウンロード</a></div>`;}).join('');}

function surveyTextAnswers(id){const item=data.portal?.items.find(x=>x.id===id);return (data.portal?.entries||[]).filter(x=>x.kind==='surveys'&&x.item_id===id).sort((a,b)=>String(b.created||'').localeCompare(String(a.created||''))).map(x=>({...x,answer:x.body.startsWith((item?.title||'')+'\n')?x.body.slice(item.title.length+1):x.body}));}
function showSurveyResults(id){if(user.role==='member')return;const item=data.portal?.items.find(x=>x.id===id&&x.kind==='surveys');if(!item)return;const form=data.surveys?.forms.find(f=>f.item_id===id);if(form?.kind==='lunch'){modal(item.title+'：結果',lunchCoachSummary(id));return;}const answers=surveyTextAnswers(id);modal(item.title+'：結果',`<div class="toolbar"><button class="lime" onclick="downloadLunch('${id}','csv')">CSVをダウンロード</button><button class="outline" onclick="downloadLunch('${id}','pdf')">PDFをダウンロード</button></div><p>回答 ${answers.length}名</p>${answers.map(a=>`<article class="card"><b>${esc(a.name)}</b><p class="hint">${esc(a.created)}</p><p class="service-text">${esc(a.answer)}</p></article>`).join('')||'<p>まだ回答はありません。</p>'}`);}
let feeHistoryMember='__all__',feeHistoryUnpaid=false,paymentMethodMember='';
function memberPaymentPanel(methodOnly=false){if(methodOnly)return paymentMethodChangesPanel();const members=(data.users||[]).filter(u=>u.role==='member');let selected=methodOnly?paymentMethodMember:feeHistoryMember;if(selected!=='__all__'&&!members.some(m=>m.id===selected))selected='__all__';if(methodOnly)paymentMethodMember=selected;else feeHistoryMember=selected;if(selected==='__all__')return allMemberPaymentsPanel(members);const rows=(data.fee_ledger?.invoices||[]).filter(r=>r.user_id===selected),method=data.fee_ledger?.methods.find(r=>r.user_id===selected);return `<div class="member-payment-panel" data-payment-panel="${methodOnly?'method':'fees'}"><div class="fee-member-selector-heading"><label for="fee-member-select">確認する会員</label><button type="button" class="outline small" onclick="changePaymentMember('__all__',false)">一つ前の画面に戻る</button></div><div class="field"><select id="fee-member-select" onchange="changePaymentMember(this.value,${methodOnly})"><option value="__all__">全て</option>${members.map(m=>`<option value="${esc(m.id)}" ${selected===m.id?'selected':''}>${esc(m.name)}（${esc(m.id)}）</option>`).join('')}</select></div>${!selected?'<p>会員が登録されていません。</p>':methodOnly?`<p>現在の支払い方法：<b>${esc(method?.method||'未登録')}</b></p><p class="hint">同じ家庭の兄弟は共通の支払い方法です。</p><details><summary>支払い方法の変更履歴</summary>${(method?.history||[]).map(h=>`<p><b>${esc(h.method)}</b><br>${esc(h.updated)}</p>`).join('')||'<p>変更履歴はありません。</p>'}</details>`:`<p>未払い・入金未確認：<b>${rows.filter(r=>!r.confirmed&&r.status!=='金額未設定').length}件</b></p><label class="check-row"><input type="checkbox" ${feeHistoryUnpaid?'checked':''} onchange="feeHistoryUnpaid=this.checked;changePaymentMember('${selected}',false)">未払い・入金未確認のみ表示</label><p class="hint">デモ手続き済みは実際の入金を意味しません。管理者が入金確認を登録します。過去の履歴は保存済みの期間が対象です。</p>${rows.filter(r=>!feeHistoryUnpaid||(!r.confirmed&&r.status!=='金額未設定')).map(r=>`<article class="card"><h3>${esc(r.period_start||r.start_month)}〜${esc(r.period_end||r.end_month)}</h3><p>会員金額：<b>${r.amount==null?'未設定':'¥'+r.amount.toLocaleString()}</b>${r.family_override?`<br>家庭一括金額：¥${Number(r.family_total).toLocaleString()}（兄弟分を含む）`:''}</p><p>支払い方法：${esc(r.method||'未登録')}<br><span class="tag ${r.confirmed?'':'warn'}">${esc(r.status)}</span>${r.demo_checkout?'<br><small>デモ手続き済み（実決済なし）</small>':''}</p>${r.confirmed_at?`<p class="hint">最終確認操作：${esc(r.confirmed_at)}</p>`:''}${user.role==='admin'?`<button class="${r.confirmed?'outline':'lime'}" onclick="confirmFeeReceipt('${r.user_id}','${r.start_month}',${!r.confirmed})">${r.confirmed?'未確認に戻す':'入金確認済みにする'}</button>`:''}</article>`).join('')||'<p>該当する記録はありません。</p>'}`}<p class="hint">ローカルの「チーターズ管理.xlsx」に会員別の履歴・支払方法を保存します。</p><div class="toolbar"><a class="btn outline" href="/basketball-club/api/excel">Excelをダウンロード</a><button class="outline" onclick="syncExcel(this)">Excelを再同期</button></div></div>`;}
function changePaymentMember(id,methodOnly){if(methodOnly)paymentMethodMember=id;else feeHistoryMember=id;const el=document.querySelector(`[data-payment-panel="${methodOnly?'method':'fees'}"]`);if(el)el.outerHTML=memberPaymentPanel(methodOnly);}
async function confirmFeeReceipt(uid,start,confirmed){try{await api('fee_receipt',{user_id:uid,start_month:start,confirmed});data=await api('data');changePaymentMember(uid,false);toast(confirmed?'入金確認を保存し、Excelに反映しました。':'未確認に戻し、Excelに反映しました。');}catch(e){toast(e.message);}}

function openScoreRecords(id){sessionStorage.setItem('club_scorecard',id);$('#modal').close();location.hash='score-records';}
function scoreRecordsPage(staff){const r=data.results.find(r=>r.id===sessionStorage.getItem('club_scorecard'));if(!staff||!r)return scorecardPage(staff);return heading('個人記録',dateLabel(r.date)+' ／ vs '+esc(r.opponent),'<a class="btn outline" href="#scorecard">スコアシートに戻る</a>')+'<article class="card">'+gameStatsForm(r.id,true)+'</article>';}

function paymentMethodChangePeople(){
 const histories=new Map();
 for(const m of data.fee_ledger?.methods||[])for(const h of m.history||[])if(h.changed_by&&h.changed_by!=='既存登録'&&!histories.has(h.id))histories.set(h.id,h);
 const people=new Map();
 for(const h of histories.values()){const person=(data.users||[]).find(u=>u.id===h.changed_by);if(!person)continue;if(!people.has(person.id))people.set(person.id,{person,history:[]});people.get(person.id).history.push(h);}
 for(const item of people.values())item.history.sort((a,b)=>b.updated.localeCompare(a.updated));
 return [...people.values()].sort((a,b)=>b.history[0].updated.localeCompare(a.history[0].updated));
}
function paymentMethodChangesPanel(){
 const people=paymentMethodChangePeople();
 const cards=people.map(({person,history})=>{const latest=history[0],current=(data.fee_ledger?.methods||[]).find(m=>m.user_id===person.id);return `<article class="card"><h3>${esc(person.name)}</h3><p>変更した支払い方法：<b>${esc(latest.method)}</b><br>変更日時：${esc(latest.updated)}</p><p>現在の支払い方法：${esc(current?.method||latest.method)}</p><details><summary>変更履歴（${history.length}件）</summary>${history.map(h=>`<p><b>${esc(h.method)}</b><br>${esc(h.updated)}</p>`).join('')}</details></article>`;});
 return `<div class="member-payment-panel" data-payment-panel="method"><p class="hint">支払い方法を登録・変更した方を新しい順に表示します。同じ家庭の兄弟は共通の支払い方法です。</p>${cards.length?cards.slice(0,2).join(''):'<p>支払い方法の登録・変更はまだありません。</p>'}${cards.length>2?`<details><summary>続きを見る（残り${cards.length-2}件）</summary>${cards.slice(2).join('')}</details>`:''}<p class="hint">ローカルの「チーターズ管理.xlsx」に会員別の履歴・支払方法を保存します。</p><div class="toolbar"><a class="btn outline" href="/basketball-club/api/excel">Excelをダウンロード</a><button class="outline" onclick="syncExcel(this)">Excelを再同期</button></div></div>`;
}

function allMemberPaymentsPanel(members){
 const invoices=data.fee_ledger?.invoices||[],period=invoices.map(r=>r.start_month).sort().at(-1)||'';
 const items=members.map(m=>{const rows=invoices.filter(r=>r.user_id===m.id);return {m,current:rows.find(r=>r.start_month===period),unpaid:rows.filter(r=>!r.confirmed&&r.status!=='金額未設定').length};});
 return `<div class="member-payment-panel" data-payment-panel="fees"><label class="field">確認する会員<select onchange="changePaymentMember(this.value,false)"><option value="__all__" selected>全て</option>${members.map(m=>`<option value="${esc(m.id)}">${esc(m.name)}</option>`).join('')}</select></label><div class="toolbar"><span class="tag">対象 ${members.length}人</span><span class="tag">最新期間の入金確認済み ${items.filter(x=>x.current?.confirmed).length}人</span><span class="tag warn">未払い・入金未確認あり ${items.filter(x=>x.unpaid).length}人</span></div><p class="hint">最新期間：${esc(period||'未登録')}から。未払い件数は過去の保存済み期間も含みます。</p><label class="check-row"><input type="checkbox" ${feeHistoryUnpaid?'checked':''} onchange="feeHistoryUnpaid=this.checked;changePaymentMember('__all__',false)">未払い・入金未確認がある会員のみ表示</label>${items.filter(x=>!feeHistoryUnpaid||x.unpaid).map(({m,current:r,unpaid})=>`<article class="fee-member-status"><div><b>${esc(m.name)}</b><small>${esc(m.enrollment?.status||(m.active?'在籍':'退会'))}</small></div><div><span class="tag ${r?.confirmed?'':'warn'}">${esc(r?.status||'請求記録なし')}</span><small>${r?esc(r.period_start||r.start_month)+'〜'+esc(r.period_end||r.end_month):'—'}</small></div><div><small>会員金額</small>${r?.amount==null?'未設定':'¥'+r.amount.toLocaleString()}${r?.family_override?`<small>家庭一括：¥${Number(r.family_total).toLocaleString()}（兄弟分を含む）</small>`:''}</div><div><small>支払い方法</small>${esc(r?.method||'未登録')}</div><div><small>過去分を含む未払い</small><b>${unpaid}件</b></div><button class="outline small" onclick="changePaymentMember('${esc(m.id)}',false)">履歴・詳細</button></article>`).join('')||'<p>該当する会員はいません。</p>'}<p class="hint">デモ手続き済みは実際の入金を意味しません。入金確認は管理者が登録します。</p><div class="toolbar"><a class="btn outline" href="/basketball-club/api/excel">Excelをダウンロード</a><button class="outline" onclick="syncExcel(this)">Excelを再同期</button></div></div>`;
}

function lunchMenuTotals(id){const totals=new Map();for(const a of data.surveys?.answers||[]){if(a.item_id!==id||a.order!=='はい')continue;for(const m of a.meals||[]){const key=JSON.stringify([m.name,Number(m.price)]);if(!totals.has(key))totals.set(key,{name:m.name,price:Number(m.price),quantity:0,total:0});const item=totals.get(key);item.quantity++;item.total+=Number(m.price);}}return [...totals.values()];}
function lunchMenuTotalsTable(id){const rows=lunchMenuTotals(id);return `<h3>メニュー別の注文合計</h3><div class="table-wrap"><table><thead><tr><th>メニュー</th><th>単価</th><th>注文数</th><th>合計金額</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.name)}</td><td>¥${r.price.toLocaleString()}</td><td>${r.quantity}個</td><td>¥${r.total.toLocaleString()}</td></tr>`).join('')||'<tr><td colspan="4">注文はありません。</td></tr>'}</tbody><tfoot><tr><th>総合計</th><td></td><td>${rows.reduce((n,r)=>n+r.quantity,0)}個</td><td>¥${rows.reduce((n,r)=>n+r.total,0).toLocaleString()}</td></tr></tfoot></table></div>`;}

function scoreNumberControl(label,name,value){const v=value??'';return `<div class="field score-number-field"><span>${esc(label)}</span><div class="score-number-controls"><select aria-label="${esc(label)}を選択" onchange="selectScoreNumber(this)"><option value="" ${v===''?'selected':''}>未記録</option>${Array.from({length:101},(_,n)=>`<option value="${n}" ${v!==''&&Number(v)===n?'selected':''}>${n}</option>`).join('')}<option value="custom" ${v!==''&&Number(v)>100?'selected':''}>直接入力</option></select><input aria-label="${esc(label)}を直接入力" name="${esc(name)}" type="number" inputmode="numeric" min="0" max="999" step="1" value="${esc(v)}" placeholder="直接入力" oninput="syncScoreNumber(this)"></div></div>`;}
function selectScoreNumber(select){const input=select.parentElement.querySelector('input');if(select.value==='custom'){input.focus();return;}input.value=select.value;}
function syncScoreNumber(input){const select=input.parentElement.querySelector('select');select.value=input.value===''?'':Number.isInteger(Number(input.value))&&Number(input.value)>=0&&Number(input.value)<=100?String(Number(input.value)):'custom';}

function billingIndividualPeriod(r,i,p){const period=r.period||p.periods[r.slot];return `<div class="form-grid"><label class="field">期間の設定<select name="profile_${i}_period_mode" onchange="changeIndividualPeriod(this,${i},true)"><option value="shared" ${!r.period?'selected':''}>一括設定と同じ</option><option value="individual" ${r.period?'selected':''}>個別の期間</option></select></label><label class="field">開始月<input type="month" name="profile_${i}_start" value="${period.start}" required onchange="changeIndividualPeriod(this,${i})"></label><label class="field">終了月<input type="month" name="profile_${i}_end" value="${period.end}" required onchange="changeIndividualPeriod(this,${i})"></label></div>`;}
function changeIndividualPeriod(el,i,modeChange=false){const form=el.form,r=data.billing_plan.profiles[i],mode=form.elements['profile_'+i+'_period_mode'],start=form.elements['profile_'+i+'_start'],end=form.elements['profile_'+i+'_end'];if(modeChange&&mode.value==='shared'){const shared=data.billing_plan.periods[r.slot];start.value=shared.start;end.value=shared.end;}else if(!modeChange)mode.value='individual';el.closest('fieldset').querySelector('[data-period-title]').textContent=r.slot+'：'+start.value+'〜'+end.value;}

function billingNoteInput(name,value){return `<label class="field">備考<textarea name="${name}" maxlength="2000" rows="2" placeholder="料金や適用条件についてのメモ">${esc(value||'')}</textarea></label>`;}

let collectionPeriod='';
function collectionPanel(){
 const c=data.fee_collection;if(!c)return '';if(!c.periods.some(p=>p.start===collectionPeriod))collectionPeriod=c.default_period||c.periods[0]?.start||'';
 const p=c.periods.find(p=>p.start===collectionPeriod),rows=c.rows.filter(r=>r.start_month===collectionPeriod);
 const yen=v=>'¥'+Number(v||0).toLocaleString('ja-JP');
 const group=(title,status)=>{const selected=rows.filter(r=>r.collection_status===status);return `<details class="collection-group" ><summary><b>${title}（${selected.length}人）</b></summary>${status==='未納入'?`<div class="toolbar"><button class="lime" onclick="downloadUnpaidCsv()">CSVをダウンロード</button><a class="btn outline" href="/basketball-club/api/fee-unpaid-excel?period=${encodeURIComponent(collectionPeriod)}">Excelをダウンロード</a><button class="outline" onclick="syncExcel(this)">Excelを再同期</button></div>`:''}${selected.map(r=>`<article class="collection-member"><div><b>${esc(r.name)}</b><p class="hint">${esc(r.period_start||r.start_month)}〜${esc(r.period_end||r.end_month)} ／ ${esc(r.method)}</p><p>徴収予定：${r.due==null?'未設定':yen(r.due)}　納入済み：${yen(r.collected)}　未納：${r.due==null?'未設定':yen(r.unpaid)}</p>${r.confirmed_at?`<small>確認日時：${esc(r.confirmed_at)}</small>`:''}${r.note?`<p class="hint">備考：${esc(r.note)}</p>`:''}</div><div class="toolbar">${!r.confirmed&&['クレジットカード','PayPay'].includes(r.method)?'<span class="hint">決済連携の準備中</span>':r.due!=null&&r.due>0?`<button class="${r.confirmed?'outline':'lime'}" onclick="collectionReceiptForm('${r.user_id}','${r.start_month}',${!r.confirmed})">${r.confirmed?'未納入に戻す':'納入済みにする'}</button>`:''}</div></article>`).join('')||'<p class="hint">該当する会員はいません。</p>'}${status==='納入済み'?`<div class="toolbar"><button class="lime" onclick="downloadCollectionCsv()" ${!p?'disabled':''}>CSVをダウンロード</button><a class="btn outline" href="/basketball-club/api/excel">Excelをダウンロード</a><button class="outline" onclick="syncExcel(this)">Excelを再同期</button></div>`:''}</details>`;};
 return `<section class="card" id="fee-collection-panel"><h2>会費の徴収状況</h2><label class="field">集計する期間<select onchange="collectionPeriod=this.value;renderCollectionPanel()">${c.periods.map(x=>`<option value="${esc(x.start)}" ${x.start===collectionPeriod?'selected':''}>${esc(x.slot+'：'+x.start+'〜'+x.end)}</option>`).join('')}</select></label><p class="hint">個別設定を優先して集計します。会員ごとの対象期間は各会員の行に表示します。納入済みは管理者が実際の入金を確認した金額です。</p>${p?`${stats([['徴収予定額',yen(p.due),''],['徴収済み額',yen(p.collected),''],['未納額',yen(p.unpaid),'']])}${p.unknown?`<p class="error">金額未設定の会員が${p.unknown}人います。未設定分は合計に含みません。</p>`:''}<details class="collection-group"><summary><b>支払い方法別の内訳</b></summary><div class="table-wrap"><table><thead><tr><th>支払い方法</th><th>徴収予定額</th><th>徴収済み額</th><th>未納額</th></tr></thead><tbody>${p.methods.map(m=>`<tr><th>${esc(m.method)}</th><td>${yen(m.due)}</td><td>${yen(m.collected)}</td><td>${yen(m.unpaid)}</td></tr>`).join('')}</tbody><tfoot><tr><th>合計</th><td>${yen(p.due)}</td><td>${yen(p.collected)}</td><td>${yen(p.unpaid)}</td></tr></tfoot></table></div><p class="hint">未納分は登録された支払い方法、納入済み分は入金確認時の支払い方法で集計します。</p></details>${group('未納入の会員','未納入')}${group('納入済みの会員','納入済み')}${rows.some(r=>r.collection_status==='金額未設定')?group('金額未設定の会員','金額未設定'):''}${rows.some(r=>r.collection_status==='納入不要')?group('納入不要（0円）の会員','納入不要'):''}`:'<p>集計する期間がありません。</p>'}<p class="hint">保存した設定・入金確認は、ローカルの「チーターズ管理.xlsx」に自動反映されます。</p></section>`;
}
function renderCollectionPanel(){const panel=document.getElementById('fee-collection-panel');if(panel)panel.outerHTML=collectionPanel();}
function collectionReceiptForm(uid,start,confirmed){const r=data.fee_collection.rows.find(r=>r.user_id===uid&&r.start_month===start);if(!r)return;modal(confirmed?'入金を確認':'未納入に戻す',`<form onsubmit="saveCollectionReceipt(event,'${uid}','${start}',${confirmed})"><p><b>${esc(r.name)}</b> ／ ${esc(r.period_start||r.start_month)}〜${esc(r.period_end||r.end_month)}</p><p>対象金額：¥${Number(r.due).toLocaleString('ja-JP')}</p>${confirmed?selectField('実際に受け取った支払い方法','method',['クレジットカード','コンビニ決済'],['クレジットカード','コンビニ決済'].includes(r.method)?r.method:'クレジットカード'):'<p>入金確認を取り消し、この期間の金額を未納額に戻します。</p>'}<div class="error" role="alert"></div><div class="toolbar"><button type="button" class="outline" onclick="document.getElementById('modal').close()">キャンセル</button><button class="lime">${confirmed?'納入済みとして保存':'未納入に戻す'}</button></div></form>`);}
async function saveCollectionReceipt(ev,uid,start,confirmed){ev.preventDefault();await submit(ev,'fee_receipt',{collection:true,user_id:uid,start_month:start,confirmed,...Object.fromEntries(new FormData(ev.target))},confirmed?'入金確認を保存し、Excelに反映しました。':'未納入に戻し、Excelに反映しました。');}
function downloadCollectionCsv(){const c=data.fee_collection,p=c?.periods.find(p=>p.start===collectionPeriod);if(!p)return;const money=v=>v==null?'未設定':Number(v).toLocaleString('ja-JP'),rows=[['集計期間',p.start+'〜'+p.end],['区分','徴収予定額（円）','徴収済み額（円）','未納額（円）'],['合計',money(p.due),money(p.collected),money(p.unpaid)],['金額未設定人数',p.unknown],[],['支払い方法','徴収予定額（円）','徴収済み額（円）','未納額（円）'],...p.methods.map(m=>[m.method,money(m.due),money(m.collected),money(m.unpaid)]),[],['会員ID','氏名','対象開始月','対象終了月','納入状態','支払い方法','徴収予定額（円）','徴収済み額（円）','未納額（円）','入金確認日時','確認者','備考'],...c.rows.filter(r=>r.start_month===collectionPeriod).map(r=>[r.user_id,r.name,r.period_start||r.start_month,r.period_end||r.end_month,r.collection_status,r.method,money(r.due),money(r.collected),r.due==null?'未設定':money(r.unpaid),r.confirmed_at,data.users.find(u=>u.id===r.confirmed_by)?.name||r.confirmed_by,r.note||''])];const cell=x=>'"'+String(x??'').replace(/^[\s]*[=+@-]/,m=>"'"+m).replace(/"/g,'""')+'"';saveDownload('\ufeff'+rows.map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8','会費徴収状況_'+p.start+'_'+p.end+'.csv');}

function downloadUnpaidCsv(){const rows=data.fee_collection.rows.filter(r=>r.start_month===collectionPeriod&&r.collection_status==='未納入');const table=[['会員ID','氏名','対象開始月','対象終了月','支払い方法','未納額（円）'],...rows.map(r=>[r.user_id,r.name,r.period_start||r.start_month,r.period_end||r.end_month,r.method,Number(r.unpaid).toLocaleString('ja-JP')])];const cell=v=>'"'+String(v??'').replace(/^[\s]*[=+@-]/,m=>"'"+m).replace(/"/g,'""')+'"';saveDownload('\ufeff'+table.map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8','未納入会員_'+collectionPeriod+'.csv');}

function visibleMemberLinks(){return memberLinks.filter(l=>(l[0]!=="school-reports"||data.school_reports?.available)&&(l[0]!=="worksheets"||data.worksheets?.available)&&(l[0]!=="basket-notes"));}

function enrollmentForm(id){const m=data.users.find(m=>m.id===id),r=m.enrollment||{status:'在籍',revision:0};modal('休会・会費請求の設定',`<form onsubmit="saveEnrollment(event,'${esc(id)}',${r.revision})"><h3>${esc(m.name)}</h3>${enrollmentStatusField('status',r)}<div data-stop-reason>${selectField('停止理由','reason',[['','選択してください'],...['けが・病気','家庭の事情','学業・受験','長期欠席','その他'].map(x=>[x,x])],r.reason||'').replace('<select ','<select onchange="toggleEnrollmentReason(this.form)" ')}<div data-other-reason>${field('その他の理由','note',r.note||'','text',false)}</div></div><p class="hint">休会中もログインできます。新しい会費請求を停止し、すでに作成された請求・入金履歴は残します。在籍に戻すと新しい請求を再開します。</p><div class="error" role="alert"></div><button class="lime">保存する</button></form>`);toggleEnrollmentReason(document.querySelector('#modal form'));}
function toggleEnrollmentReason(f){f.querySelector('[data-stop-reason]').hidden=!f.elements.status.value.includes('休会');f.querySelector('[data-other-reason]').hidden=f.elements.reason.value!=='その他';}
async function saveEnrollment(ev,id,revision){ev.preventDefault();await submit(ev,'enrollment',{...Object.fromEntries(new FormData(ev.target)),user_id:id,revision},'在籍状況と会費請求の設定を保存しました。');}

const memberProgressYears=new Map();
function memberProgressCards(){const state=data.member_progress;if(!state)return '';const selected=memberProgressYears.get(user.id),row=state.years.find(y=>y.year===selected)||state.years.find(y=>y.year===state.current_year),rate=v=>v==null?'未集計':v+'%';if(!row)return '';return `<section class="member-progress"><h3>${esc(user.name)}さんの出席・提出状況</h3><label class="field">表示する年度<select onchange="memberProgressYears.set(user.id,Number(this.value));dashboard()">${state.years.map(y=>`<option value="${y.year}" ${y.year===row.year?'selected':''}>${y.year}年度（${y.year}年4月〜${y.year+1}年3月）</option>`).join('')}</select></label><p class="hint">集計期間：${row.start}〜${row.end}（本日までの記録）</p><div class="stats"><div class="stat"><div class="label">出席率</div><div class="stat-value"><strong>${rate(row.attendance_rate)}</strong></div><p class="hint">出席 ${row.present}回 ／ 確認済み ${row.confirmed}回<br>遅刻・早退を含み、未来・未確認は除外</p></div><div class="stat"><div class="label">バスケノート提出率</div><div class="stat-value"><strong>${row.note_applicable?rate(row.note_rate):'対象外'}</strong></div><p class="hint">${row.note_applicable?`提出 ${row.submitted_days}日 ／ 実際の出席 ${row.attended_days}日`:'この年度のバスケノート対象記録はありません。'}</p></div></div></section>`;}

function campSurveyForm(id){const saved=ownSurveyAnswer(id)?.answer?.body||'';return `<form class="camp-survey" onsubmit="saveCampSurvey(event,'${id}')">${[['watch','保護者見守り'],['serving','配膳']].map(([key,label])=>{const line=saved.split('\n').find(x=>x.startsWith(label+'：'))||'',selected=['一部可能','不可能','可能'].find(x=>line.startsWith(label+'：'+x))||'',times=line.match(/（(\d{2}:\d{2})〜(\d{2}:\d{2})）/);return `<fieldset class="camp-help"><legend>${label}</legend><div class="camp-options">${['可能','不可能','一部可能'].map(v=>`<label><input type="radio" name="${key}" value="${v}" required ${selected===v?'checked':''} onchange="toggleCampTime(this)"><span>${v}</span></label>`).join('')}</div><div class="camp-times" ${selected==='一部可能'?'':'hidden'}>${['start','end'].map((part,i)=>`<label class="field">${i?'終了時刻':'開始時刻'}<input type="time" name="${key}_${part}" value="${times?.[i+1]||''}" ${selected==='一部可能'?'required':'disabled'}></label>`).join('')}</div></fieldset>`;}).join('')}<label class="field">備考（任意）<textarea name="note" maxlength="2000">${esc(saved.includes('備考：')?saved.split('備考：').slice(1).join('備考：'):'')}</textarea></label><div class="error" role="alert"></div><button class="lime">${saved?'回答を更新':'回答を送信'}</button></form>`;}
function toggleCampTime(input){const box=input.closest('fieldset').querySelector('.camp-times'),partial=input.value==='一部可能';box.hidden=!partial;box.querySelectorAll('input').forEach(el=>{el.disabled=!partial;el.required=partial;});}
async function saveCampSurvey(ev,id){ev.preventDefault();const f=data.surveys.forms.find(x=>x.item_id===id);await submit(ev,'portal',{...Object.fromEntries(new FormData(ev.target)),kind:'surveys',item_id:id,revision:f.revision},'合宿アンケートを保存しました。');}

function scoreResourcePanel(id){const r=(data.score_resources||[]).find(x=>x.result_id===id);return `<section class="score-resources"><h2>共有スコアシート・PDF</h2>${adminCan('results',true)?`<button class="lime" onclick="scoreResourceForm('${id}')">スコアシートを編集</button>`:''}<div class="dialog-actions">${r?.url?`<a class="btn outline" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">共有スコアシートを開く</a>`:''}</div>${(r?.files||[]).map(f=>`<div class="card"><b>${esc(f.name)}</b><div class="dialog-actions"><a class="btn outline" href="/basketball-club/api/score_resource_file?id=${encodeURIComponent(f.id)}" target="_blank" rel="noopener noreferrer">PDFを表示</a><a class="btn outline" href="/basketball-club/api/score_resource_file?id=${encodeURIComponent(f.id)}&download=1" download>ダウンロード</a></div></div>`).join('')}${!r?.url&&!r?.files.length?'<p class="hint">共有URL・PDFは未登録です。</p>':''}</section>`;}
function scoreResourceForm(id){const r=(data.score_resources||[]).find(x=>x.result_id===id)||{revision:0,files:[]};modal('スコアシートを編集',`<form onsubmit="saveScoreResource(event,'${id}',${r.revision})">${field('共有URL（HOOPAPPSなど）','url',r.url||'','url',false)}<p class="hint">発行された共有URLを貼り付けてください。保存後は別タブで開けます。</p><fieldset><legend>保存済みPDF（残すものにチェック）</legend>${r.files.map(f=>`<label class="check-row"><input type="checkbox" name="keep" value="${esc(f.id)}" checked>${esc(f.name)}</label>`).join('')||'PDFは未登録です。'}</fieldset><label class="field">PDFを追加（合計30件まで・1件5MB以下）<input type="file" name="attachments" accept="application/pdf,.pdf" multiple></label><p class="hint">この試合のスコアシートに共有URLとPDFを表示します。複数回に分けて追加できます。</p><div class="error" role="alert"></div><button class="lime">保存する</button></form>`);}
async function saveScoreResource(ev,id,revision){ev.preventDefault();try{const f=new FormData(ev.target),uploads=await submissionUploads(ev.target);await submit(ev,'score_resource',{result_id:id,revision,url:f.get('url'),keep:f.getAll('keep'),uploads},'スコアシートを保存しました。');}catch(e){ev.target.querySelector('.error').textContent=e.message;}}
